(window.QDATA=window.QDATA||{})[12]={"s":12,"ar":"يوسف","tl":"Yusuf","n":111,"place":"makkah","bism":true,"mean":{"en":"Joseph","ur":"یوسف","hi":"यूसुफ़"},"v":[{"a":1,"ar":" الٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْمُبِينِ","en":"Alif, Lām, Rā. These are the verses of the clear Book.","ur":"الٓرا۔ یہ کتاب روشن کی آیتیں ہیں","hi":"अलिफ़, लाम, रा। ये स्पष्ट किताब की आयतें हैं।"},{"a":2,"ar":"إِنَّآ أَنزَلْنَـٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ","en":"Indeed, We have sent it down as an Arabic Qur’ān that you might understand.","ur":"ہم نے اس قرآن کو عربی میں نازل کیا ہے تاکہ تم سمجھ سکو","hi":"निःसंदेह हमने इस क़ुरआन को अरबी में उतारा है, ताकि तुम समझो।"},{"a":3,"ar":"نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَـٰذَا ٱلْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ٱلْغَـٰفِلِينَ","en":"We relate to you, [O Muḥammad], the best of stories in what We have revealed to you of this Qur’ān although you were, before it, among the unaware.","ur":"(اے پیغمبر) ہم اس قرآن کے ذریعے سے جو ہم نے تمہاری طرف بھیجا ہے تمہیں ایک نہایت اچھا قصہ سناتے ہیں اور تم اس سے پہلے بےخبر تھے","hi":"(ऐ नबी!) हम आपकी ओर इस क़ुरआन की वह़्य करके, आपके सामने एक बहुत अच्छा क़िस्सा बयान कर रहे हैं। निश्चय ही आप इससे पूर्व अनजानों में से थे।"},{"a":4,"ar":"إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَـٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَـٰجِدِينَ","en":"[Of these stories mention] when Joseph said to his father, \"O my father, indeed I have seen [in a dream] eleven stars and the sun and the moon; I saw them prostrating to me.\"","ur":"جب یوسف نے اپنے والد سے کہا کہ ابا میں نے (خواب میں) گیارہ ستاروں اور سورج اور چاند کو دیکھا ہے۔ دیکھتا (کیا) ہوں کہ وہ مجھے سجدہ کر رہے ہیں","hi":"जब यूसुफ़ ने अपने पिता से कहा : ऐ मेरे पिता! मैंने सपना देखा है कि ग्यारह सितारे, सूर्य तथा चाँद मुझे सजदा कर रहे हैं।"},{"a":5,"ar":"قَالَ يَـٰبُنَىَّ لَا تَقْصُصْ رُءْيَاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُوا۟ لَكَ كَيْدًا ۖ إِنَّ ٱلشَّيْطَـٰنَ لِلْإِنسَـٰنِ عَدُوٌّ مُّبِينٌ","en":"He said, \"O my son, do not relate your vision to your brothers or they will contrive against you a plan. Indeed Satan, to man, is a manifest enemy.","ur":"انہوں نے کہا کہ بیٹا اپنے خواب کا ذکر اپنے بھائیوں سے نہ کرنا نہیں تو وہ تمہارے حق میں کوئی فریب کی چال چلیں گے۔ کچھ شک نہیں کہ شیطان انسان کا کھلا دشمن ہے","hi":"उसने कहा : ऐ मेरे बेटे! अपना स्वप्न अपने भाइयों को न बताना, अन्यथा वे तेरे विरुद्ध कोई चाल चलेंगे। निःसंदेह शैतान इनसान का खुला दुश्मन है।"},{"a":6,"ar":"وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُۥ عَلَيْكَ وَعَلَىٰٓ ءَالِ يَعْقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيْكَ مِن قَبْلُ إِبْرَٰهِيمَ وَإِسْحَـٰقَ ۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ","en":"And thus will your Lord choose you and teach you the interpretation of narratives [i.e., events or dreams] and complete His favor upon you and upon the family of Jacob, as He completed it upon your fathers before, Abraham and Isaac. Indeed, your Lord is Knowing and Wise.\"","ur":"اور اسی طرح خدا تمہیں برگزیدہ (وممتاز) کرے گا اور (خواب کی) باتوں کی تعبیر کا علم سکھائے گا۔ اور جس طرح اس نے اپنی نعمت پہلے تمہارے دادا، پردادا ابراہیم اور اسحاق پر پوری کی تھی اسی طرح تم پر اور اولاد یعقوب پر پوری کرے گا۔ بےشک تمہارا پروردگار (سب کچھ) جاننے والا (اور) حکمت والا ہے","hi":"और ऐसे ही तेरा पालनहार तुझे चुन लेगा तथा तुझे बातों (सपनों) का अर्थ सिखाएगा और तुझपर और याक़ूब के घराने पर अपना अनुग्रह पूरा करेगा, जिस तरह उसने इससे पहले उसे तेरे बाप-दादा इबराहीम और इसह़ाक़ पर पूरा किया था। निःसंदेह तेरा पालनहार सब कुछ जानने वाला, पूर्ण हिकमत वाला है।"},{"a":7,"ar":"۞ لَّقَدْ كَانَ فِى يُوسُفَ وَإِخْوَتِهِۦٓ ءَايَـٰتٌ لِّلسَّآئِلِينَ","en":"Certainly were there in Joseph and his brothers signs for those who ask, [such as]","ur":"ہاں یوسف اور ان کے بھائیوں (کے قصے) میں پوچھنے والوں کے لیے (بہت سی) نشانیاں ہیں","hi":"वास्तव में, यूसुफ़ और उसके भाइयों (की कहानी) में पूछने वालों के लिए कई निशानियाँ हैं।"},{"a":8,"ar":"إِذْ قَالُوا۟ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِى ضَلَـٰلٍ مُّبِينٍ","en":"When they said, \"Joseph and his brother are more beloved to our father than we, while we are a clan. Indeed, our father is in clear error.","ur":"جب انہوں نے (آپس میں) تذکرہ کیا کہ یوسف اور اس کا بھائی ابا کو ہم سے زیادہ پیارے ہیں حالانکہ ہم جماعت (کی جماعت) ہیں۔ کچھ شک نہیں کہ ابا صریح غلطی پر ہیں","hi":"जब उन (भाइयों) ने कहा : यूसुफ़ और उसका भाई हमारे पिता को, हमसे अधिक प्रिय हैं। जबकि हम एक गिरोह हैं। वास्तव में, हमारे पिता खुली गुमराही में हैं।"},{"a":9,"ar":"ٱقْتُلُوا۟ يُوسُفَ أَوِ ٱطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا۟ مِنۢ بَعْدِهِۦ قَوْمًا صَـٰلِحِينَ","en":"Kill Joseph or cast him out to [another] land; the countenance [i.e., attention] of your father will [then] be only for you, and you will be after that a righteous people.\"","ur":"تو یوسف کو (یا تو جان سے) مار ڈالو یا کسی ملک میں پھینک آؤ۔ پھر ابا کی توجہ صرف تمہاری طرف ہوجائے گی۔ اور اس کے بعد تم اچھی حالت میں ہوجاؤ گے","hi":"यूसुफ़ को मार डालो या उसे किसी धरती में फेंक आओ। ताकि तुम्हारे पिता का ध्यान केवल तुम्हारी तरफ हो जाए और इसके बाद तुम नेक बन जाओ।"},{"a":10,"ar":"قَالَ قَآئِلٌ مِّنْهُمْ لَا تَقْتُلُوا۟ يُوسُفَ وَأَلْقُوهُ فِى غَيَـٰبَتِ ٱلْجُبِّ يَلْتَقِطْهُ بَعْضُ ٱلسَّيَّارَةِ إِن كُنتُمْ فَـٰعِلِينَ","en":"Said a speaker among them, \"Do not kill Joseph but throw him into the bottom of the well; some travelers will pick him up - if you would do [something].\"","ur":"ان میں سے ایک کہنے والے نے کہا کہ یوسف کو جان سے نہ مارو کسی گہرے کنویں میں ڈال دو کہ کوئی راہگیر نکال (کر اور ملک میں) لے جائے گا۔ اگر تم کو کرنا ہے (تو یوں کرو)","hi":"उनमें से एक कहने वाले ने कहा : यूसुफ़ का वध न करो। उसे किसी गहरे कुएँ के अंदर डाल दो। उसे कोई कारवाँ निकाल ले जाएगा, यदि कुछ करने वाले हो।"},{"a":11,"ar":"قَالُوا۟ يَـٰٓأَبَانَا مَا لَكَ لَا تَأْمَ۫نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَـٰصِحُونَ","en":"They said, \"O our father, why do you not entrust us with Joseph while indeed, we are to him sincere counselors?","ur":"(یہ مشورہ کر کے وہ یعقوب سے) کہنے لگے کہ اباجان کیا سبب ہے کہ آپ یوسف کے بارے میں ہمارا اعتبار نہیں کرتے حالانکہ ہم اس کے خیرخواہ ہیں","hi":"उन्होंने कहा : ऐ हमारे पिता! क्या बात है कि यूसुफ़ के विषय में आप हमपर विश्वास नहीं करते? जबकि हम लोग उसका भला चाहने वाले हैं।"},{"a":12,"ar":"أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ","en":"Send him with us tomorrow that he may eat well and play. And indeed, we will be his guardians.\"","ur":"کل اسے ہمارے ساتھ بھیج دیجیئے کہ خوب میوے کھائے اور کھیلے کودے۔ ہم اس کے نگہبان ہیں","hi":"उसे कल हमारे साथ भेज दें, वह खाए-पिए और खेले-कूदे, और निःसंदेह हम उसकी रक्षा करने वाले हैं।"},{"a":13,"ar":"قَالَ إِنِّى لَيَحْزُنُنِىٓ أَن تَذْهَبُوا۟ بِهِۦ وَأَخَافُ أَن يَأْكُلَهُ ٱلذِّئْبُ وَأَنتُمْ عَنْهُ غَـٰفِلُونَ","en":"[Jacob] said, \"Indeed, it saddens me that you should take him, and I fear that a wolf would eat him while you are of him unaware.\"","ur":"انہوں نے کہا کہ یہ امر مجھے غمناک کئے دیتا ہے کہ تم اسے لے جاؤ (یعنی وہ مجھ سے جدا ہوجائے) اور مجھے یہ خوف بھی ہے کہ تم (کھیل میں) اس سے غافل ہوجاؤ اور اسے بھیڑیا کھا جائے","hi":"उस (याक़ूब) ने कहा : यह मेरे लिए दुःख की बात है कि तुम उसे ले जाओ, तथा मैं इस बात से (भी) डरता हूँ कि उसे भेड़िया खा जाए और तुम उसका ध्यान न रख सको।"},{"a":14,"ar":"قَالُوا۟ لَئِنْ أَكَلَهُ ٱلذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّآ إِذًا لَّخَـٰسِرُونَ","en":"They said, \"If a wolf should eat him while we are a [strong] clan, indeed, we would then be losers.\"","ur":"وہ کہنے لگے کہ اگر ہماری موجودگی میں کہ ہم ایک طاقتور جماعت ہیں، اسے بھیڑیا کھا گیا تو ہم بڑے نقصان میں پڑگئے","hi":"उन्होंने कहा : यदि उसे भेड़िया खा गया, जबकि हम एक गिरोह हैं, तो वास्तव में, हम बड़े घाटे वाले हैं।"},{"a":15,"ar":"فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَـٰبَتِ ٱلْجُبِّ ۚ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَـٰذَا وَهُمْ لَا يَشْعُرُونَ","en":"So when they took him [out] and agreed to put him into the bottom of the well... But We inspired to him, \"You will surely inform them [someday] about this affair of theirs while they do not perceive [your identity].\"","ur":"غرض جب وہ اس کو لے گئے اور اس بات پر اتفاق کرلیا کہ اس کو گہرے کنویں میں ڈال دیں۔ تو ہم نے یوسف کی طرف وحی بھیجی کہ (ایک وقت ایسا آئے گا کہ) تم ان کے اس سلوک سے آگاہ کرو گے اور ان کو (اس وحی کی) کچھ خبر نہ ہوگی","hi":"फिर जब वे उसे ले गए और निश्चय कर लिया कि उसे गहरे कुएँ के अंदर डाल देंगे और हमने उस (यूसुफ़) की ओर वह़्य कर दी कि तुम अवश्य इन्हें इनके इस कर्म के बारे में बताओगे और वे कुछ जानते न होंगे।"},{"a":16,"ar":"وَجَآءُوٓ أَبَاهُمْ عِشَآءً يَبْكُونَ","en":"And they came to their father at night, weeping.","ur":"(یہ حرکت کرکے) وہ رات کے وقت باپ کے پاس روتے ہوئے آئے","hi":"और वे इशा के वक़्त रोते हुए अपने पिता के पास आए।"},{"a":17,"ar":"قَالُوا۟ يَـٰٓأَبَانَآ إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِندَ مَتَـٰعِنَا فَأَكَلَهُ ٱلذِّئْبُ ۖ وَمَآ أَنتَ بِمُؤْمِنٍ لَّنَا وَلَوْ كُنَّا صَـٰدِقِينَ","en":"They said, \"O our father, indeed we went racing each other and left Joseph with our possessions, and a wolf ate him. But you would not believe us, even if we were truthful.\"","ur":"(اور) کہنے لگے کہ اباجان ہم تو دوڑنے اور ایک دوسرے سے آگے نکلنے میں مصروف ہوگئے اور یوسف کو اپنے اسباب کے پاس چھوڑ گئے تو اسے بھیڑیا کھا گیا۔ اور آپ ہماری بات کو گو ہم سچ ہی کہتے ہوں باور نہیں کریں گے","hi":"उन्होंने कहा : ऐ हमारे पिता! हम आपस में दौड़ का मुक़ाबला करने लगे और यूसुफ़ को अपने सामान के पास छोड़ दिया। इतने में उसे भेड़िया खा गया। और आप तो हमारा विश्वास करने वाले नहीं हैं, यद्यपि हम सच ही क्यों न बोल रहे हों।"},{"a":18,"ar":"وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٍ كَذِبٍ ۚ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا ۖ فَصَبْرٌ جَمِيلٌ ۖ وَٱللَّهُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ","en":"And they brought upon his shirt false blood. [Jacob] said, \"Rather, your souls have enticed you to something, so patience is most fitting. And Allāh is the one sought for help against that which you describe.\"","ur":"اور ان کے کرتے پر جھوٹ موٹ کا لہو بھی لگا لائے۔ یعقوب نے کہا (کہ حقیقت حال یوں نہیں ہے) بلکہ تم اپنے دل سے (یہ) بات بنا لائے ہو۔ اچھا صبر (کہ وہی) خوب (ہے) اور جو تم بیان کرتے ہو اس کے بارے میں خدا ہی سے مدد مطلوب ہے","hi":"और वे उस (यूसुफ़) के कुर्ते पर झूठा रक्त लगाकर लाए। उस (याक़ूब) ने कहा : बल्कि तुम्हारे मन ने तुम्हारे लिए एक चीज़ को सुंदर बना दिया है! सो अब (मेरा काम) बेहतर सब्र करना है और जो बात तुम बना रहे हो, उसपर अल्लाह ही सहायक है।"},{"a":19,"ar":"وَجَآءَتْ سَيَّارَةٌ فَأَرْسَلُوا۟ وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُۥ ۖ قَالَ يَـٰبُشْرَىٰ هَـٰذَا غُلَـٰمٌ ۚ وَأَسَرُّوهُ بِضَـٰعَةً ۚ وَٱللَّهُ عَلِيمٌۢ بِمَا يَعْمَلُونَ","en":"And there came a company of travelers; then they sent their water drawer, and he let down his bucket. He said, \"Good news! Here is a boy.\" And they concealed him, [taking him] as merchandise; and Allāh was Knowing of what they did.","ur":"(اب خدا کی شان دیکھو کہ اس کنویں کے قریب) ایک قافلہ آوارد ہوا اور انہوں نے (پانی کے لیے) اپنا سقا بھیجا۔ اس نے کنویں میں ڈول لٹکایا (تو یوسف اس سے لٹک گئے) وہ بولا زہے قسمت یہ تو (نہایت حسین) لڑکا ہے۔ اور اس کو قیمتی سرمایہ سمجھ کر چھپا لیا اور جو کچھ وہ کرتے تھے خدا کو سب معلوم تھا","hi":"और एक क़ाफ़िला आया। उसने अपने पानी भरने वाले को भेजा, उसने अपना डोल डाला, तो पुकार उठा : अरे, कितनी खुशी की बात है! यह तो एक बालक है। और उन्होंने उसे व्यापार का माल समझकर छिपा लिया और वे जो कुछ कर रहे थे अल्लाह उसे ख़ूब जानने वाला है।"},{"a":20,"ar":"وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍ دَرَٰهِمَ مَعْدُودَةٍ وَكَانُوا۟ فِيهِ مِنَ ٱلزَّٰهِدِينَ","en":"And they sold him for a reduced price - a few dirhams - and they were, concerning him, of those content with little.","ur":"اور اس کو تھوڑی سی قیمت (یعنی) معدودے چند درہموں پر بیچ ڈالا۔ اور انہیں ان (کے بارے) میں کچھ لالچ نہ تھا","hi":"और उन्होंने उसे थोड़े से मूल्य; गिनती के कुछ दिरहमों में बेच दिया और वे उसके बारे में कुछ अधिक की इच्छा नहीं रखते थे।"},{"a":21,"ar":"وَقَالَ ٱلَّذِى ٱشْتَرَىٰهُ مِن مِّصْرَ لِٱمْرَأَتِهِۦٓ أَكْرِمِى مَثْوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا ۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ وَلِنُعَلِّمَهُۥ مِن تَأْوِيلِ ٱلْأَحَادِيثِ ۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمْرِهِۦ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ","en":"And the one from Egypt who bought him said to his wife, \"Make his residence comfortable. Perhaps he will benefit us, or we will adopt him as a son.\" And thus, We established Joseph in the land that We might teach him the interpretation of events [i.e., dreams]. And Allāh is predominant over His affair, but most of the people do not know.","ur":"اور مصر میں جس شخص نے اس کو خریدا اس نے اپنی بیوی سے (جس کا نام زلیخا تھا) کہا کہ اس کو عزت واکرام سے رکھو عجب نہیں کہ یہ ہمیں فائدہ دے یا ہم اسے بیٹا بنالیں۔ اس طرح ہم نے یوسف کو سرزمین (مصر) میں جگہ دی اور غرض یہ تھی کہ ہم ان کو (خواب کی) باتوں کی تعبیر سکھائیں اور خدا اپنے کام پر غالب ہے لیکن اکثر لوگ نہیں جانتے","hi":"और मिस्र के जिस व्यक्ति ने उसे खरीदा था, उसने अपनी पत्नी से कहा : इसे आदर-मान से रखो। संभव है यह हमें लाभ पहुँचाए, अथवा हम इसे अपना पुत्र बना लें। इस प्रकार उस भूभाग में हमने यूसुफ़ के लिए क़दम जमाने की राह निकाली और ताकि उसे बातों (सपनों) का अर्थ सिखाएँ। और अल्लाह अपना आदेश पूरा करके रहता है। परन्तु अधिकतर लोग नहीं जानते।"},{"a":22,"ar":"وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَـٰهُ حُكْمًا وَعِلْمًا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ","en":"And when he [i.e., Joseph] reached maturity, We gave him judgement and knowledge. And thus We reward the doers of good.","ur":"اور جب وہ اپنی جوانی کو پہنچے تو ہم نے ان کو دانائی اور علم بخشا۔ اور نیکوکاروں کو ہم اسی طرح بدلہ دیا کرتے ہیں","hi":"और जब वह अपनी जवानी को पहुँचा और मज़बूत व तवाना हो गया, तो हमने उसे प्रबोध तथा ज्ञान प्रदान किया और इसी प्रकार हम सदाचारियों को बदला देते हैं।"},{"a":23,"ar":"وَرَٰوَدَتْهُ ٱلَّتِى هُوَ فِى بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ ٱلْأَبْوَٰبَ وَقَالَتْ هَيْتَ لَكَ ۚ قَالَ مَعَاذَ ٱللَّهِ ۖ إِنَّهُۥ رَبِّىٓ أَحْسَنَ مَثْوَاىَ ۖ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّـٰلِمُونَ","en":"And she, in whose house he was, sought to seduce him. She closed the doors and said, \"Come, you.\" He said, \"[I seek] the refuge of Allāh. Indeed, he is my master, who has made good my residence. Indeed, wrongdoers will not succeed.\"","ur":"تو جس عورت کے گھر میں وہ رہتے تھے اس نے ان کو اپنی طرف مائل کرنا چاہا اور دروازے بند کرکے کہنے لگی (یوسف) جلدی آؤ۔ انہوں نے کہا کہ خدا پناہ میں رکھے (وہ یعنی تمہارے میاں) تو میرے آقا ہیں انہوں نے مجھے اچھی طرح سے رکھا ہے (میں ایسا ظلم نہیں کرسکتا) بےشک ظالم لوگ فلاح نہیں پائیں گے","hi":"और उस स्त्री ने उसके मन को रिझाया, जिसके घर में वह था। और द्वार बंद कर लिए और बोली : आ जाओ। उसने कहा : अल्लाह की पनाह! वह मेरा मालिक है। उसने मेरे निवास को अच्छा बनाया। वास्तव में, ज़ालिम लोग सफल नहीं होते।"},{"a":24,"ar":"وَلَقَدْ هَمَّتْ بِهِۦ ۖ وَهَمَّ بِهَا لَوْلَآ أَن رَّءَا بُرْهَـٰنَ رَبِّهِۦ ۚ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ ٱلسُّوٓءَ وَٱلْفَحْشَآءَ ۚ إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُخْلَصِينَ","en":"And she certainly determined [to seduce] him, and he would have inclined to her had he not seen the proof [i.e., sign] of his Lord. And thus [it was] that We should avert from him evil and immorality. Indeed, he was of Our chosen servants.","ur":"اور اس عورت نے ان کا قصد کیا اور انہوں نے اس کا قصد کیا۔ اگر وہ اپنے پروردگار کی نشانی نہ دیکھتے (تو جو ہوتا ہوتا) یوں اس لیے (کیا گیا) کہ ہم ان سے برائی اور بےحیائی کو روک دیں۔ بےشک وہ ہمارے خالص بندوں میں سے تھے","hi":"और निश्चय ही वह स्त्री उसकी इच्छा कर चुकी थी। और वह (यूसुफ़) भी उसकी इच्छा कर लेता, यदि अपने पालनहार का प्रमाण न देख लेता। हमने ऐसा इसलिए किया ताकि बुराई एवं अश्लीलता को उससे दूर रखें। वास्तव में, वह हमारे चुने हुए बंदों में से था।"},{"a":25,"ar":"وَٱسْتَبَقَا ٱلْبَابَ وَقَدَّتْ قَمِيصَهُۥ مِن دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَا ٱلْبَابِ ۚ قَالَتْ مَا جَزَآءُ مَنْ أَرَادَ بِأَهْلِكَ سُوٓءًا إِلَّآ أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ","en":"And they both raced to the door, and she tore his shirt from the back, and they found her husband at the door. She said, \"What is the recompense of one who intended evil for your wife but that he be imprisoned or a painful punishment?\"","ur":"اور دونوں دروازے کی طرف بھاگے (آگے یوسف اور پیچھے زلیخا) اور عورت نے ان کا کرتا پیچھے سے (پکڑ کر جو کھینچا تو) پھاڑ ڈالا اور دونوں کو دروازے کے پاس عورت کا خاوند مل گیا تو عورت بولی کہ جو شخص تمہاری بیوی کے ساتھ برا ارادہ کرے اس کی اس کے سوا کیا سزا ہے کہ یا تو قید کیا جائے یا دکھ کا عذاب دیا جائے","hi":"और दोनों दरवाज़े की ओर दौड़े और उस (स्त्री) ने यूसुफ़ का कुर्ता पीछे से फाड़ डाला और दोनों ने उस (स्त्री) के पति को दरवाज़े के पास पाया। उस (स्त्री) ने कहा : जिसने तेरी पत्नी के साथ बुराई का इरादा किया, उसकी सज़ा इसके सिवा क्या हो सकती है कि उसे बंदी बनाया जाए या उसे दर्दनाक सज़ा (दी जाए)?"},{"a":26,"ar":"قَالَ هِىَ رَٰوَدَتْنِى عَن نَّفْسِى ۚ وَشَهِدَ شَاهِدٌ مِّنْ أَهْلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ ٱلْكَـٰذِبِينَ","en":"[Joseph] said, \"It was she who sought to seduce me.\" And a witness from her family testified, \"If his shirt is torn from the front, then she has told the truth, and he is of the liars.","ur":"یوسف نے کہا اسی نے مجھ کو اپنی طرف مائل کرنا چاہا تھا۔ اس کے قبیلے میں سے ایک فیصلہ کرنے والے نے فیصلہ کیا کہ اگر اس کا کرتا آگے سے پھٹا تو یہ سچی اور یوسف جھوٹا","hi":"उसने कहा : इसी ने मुझे रिझाना चाहा था और उस स्त्री के घराने से एक गवाह ने गवाही दी कि यदि उसका कुर्ता आगे से फाड़ा गया है, तो वह (महिला) सच्ची है और वह झूठा है।"},{"a":27,"ar":"وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ ٱلصَّـٰدِقِينَ","en":"But if his shirt is torn from the back, then she has lied, and he is of the truthful.\"","ur":"اور اگر کرتا پیچھے سے پھٹا ہو تو یہ جھوٹی اور وہ سچا ہے","hi":"और यदि उसका कुर्ता पीछे से फाड़ा गया है, तो वह (महिला) झूठी और वह (यूसुफ़) सच्चा है।"},{"a":28,"ar":"فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٍ قَالَ إِنَّهُۥ مِن كَيْدِكُنَّ ۖ إِنَّ كَيْدَكُنَّ عَظِيمٌ","en":"So when he [i.e., her husband] saw his shirt torn from the back, he said, \"Indeed, it is of your [i.e., women's] plan. Indeed, your plan is great [i.e., vehement].","ur":"اور جب اس کا کرتا دیکھا (تو) پیچھے سے پھٹا تھا (تب اس نے زلیخا سے کہا) کہ یہ تمہارا ہی فریب ہے۔ اور کچھ شک نہیں کہ تم عورتوں کے فریب بڑے (بھاری) ہوتے ہیں","hi":"फिर जब उस (अज़ीज़) ने देखा कि उसका कुर्ता पीछे से फाड़ा गया है, तो बोला : निःसंदेह ये तुम स्त्रियों की चाल है और निश्चय ही तुम्हारी चाल बड़ी घोर होती है।"},{"a":29,"ar":"يُوسُفُ أَعْرِضْ عَنْ هَـٰذَا ۚ وَٱسْتَغْفِرِى لِذَنۢبِكِ ۖ إِنَّكِ كُنتِ مِنَ ٱلْخَاطِـِٔينَ","en":"Joseph, ignore this. And, [my wife], ask forgiveness for your sin. Indeed, you were of the sinful.\"","ur":"یوسف اس بات کا خیال نہ کر۔ اور (زلیخا) تو اپنے گناہوں کی بخشش مانگ، بےشک خطا تیری ہے","hi":"ऐ यूसुफ़! तुम इस बात को जाने दो और (ऐ स्त्री!) तू अपने पाप की क्षमा माँग। निःसंदेह तू ही पापियों में से है।"},{"a":30,"ar":"۞ وَقَالَ نِسْوَةٌ فِى ٱلْمَدِينَةِ ٱمْرَأَتُ ٱلْعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفْسِهِۦ ۖ قَدْ شَغَفَهَا حُبًّا ۖ إِنَّا لَنَرَىٰهَا فِى ضَلَـٰلٍ مُّبِينٍ","en":"And women in the city said, \"The wife of al-ʿAzeez is seeking to seduce her slave boy; he has impassioned her with love. Indeed, we see her [to be] in clear error.\"","ur":"اور شہر میں عورتیں گفتگوئیں کرنے لگیں کہ عزیز کی بیوی اپنے غلام کو اپنی طرف مائل کرنا چاہتی ہے۔ اور اس کی محبت اس کے دل میں گھر کرگئی ہے۔ ہم دیکھتی ہیں کہ وہ صریح گمراہی میں ہے","hi":"नगर की कुछ स्त्रियों ने कहा : अज़ीज़ (प्रमुख अधिकारी) की पत्नी, अपने दास को रिझा रही है! उसे उसके प्रेम ने मुग्ध कर दिया है। हमारे विचार में वह खुली गुमराही में है।"},{"a":31,"ar":"فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَـًٔا وَءَاتَتْ كُلَّ وَٰحِدَةٍ مِّنْهُنَّ سِكِّينًا وَقَالَتِ ٱخْرُجْ عَلَيْهِنَّ ۖ فَلَمَّا رَأَيْنَهُۥٓ أَكْبَرْنَهُۥ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَـٰشَ لِلَّهِ مَا هَـٰذَا بَشَرًا إِنْ هَـٰذَآ إِلَّا مَلَكٌ كَرِيمٌ","en":"So when she heard of their scheming, she sent for them and prepared for them a banquet and gave each one of them a knife and said [to Joseph], \"Come out before them.\" And when they saw him, they greatly admired him and cut their hands and said, \"Perfect is Allāh! This is not a man; this is none but a noble angel.\"","ur":"جب زلیخا نے ان عورتوں کی (گفتگو جو حقیقت میں دیدار یوسف کے لیے ایک) چال (تھی) سنی تو ان کے پاس (دعوت کا) پیغام بھیجا اور ان کے لیے ایک محفل مرتب کی۔ اور (پھل تراشنے کے لیے) ہر ایک کو ایک چھری دی اور (یوسف سے) کہا کہ ان کے سامنے باہر آؤ۔ جب عورتوں نے ان کو دیکھا تو ان کا رعب (حسن) ان پر (ایسا) چھا گیا کہ (پھل تراشتے تراشتے) اپنے ہاتھ کاٹ لیے اور بےساختہ بول اٹھیں کہ سبحان الله (یہ حسن) یہ آدمی نہیں کوئی بزرگ فرشتہ ہے","hi":"चुनाँचे जब उसने उन स्त्रियों की छलकपट की बात सुनी, तो उन्हें बुला भेजा और उनके लिए गाव-तकिए लगवाए और प्रत्येक स्त्री को एक छुरी दे दी। और उसने (यूसुफ़ से) कहा : इनके सामने आ जाओ। फिर जब उन स्त्रियों ने उसे देखा, तो उन्होंने उसे बहुत बड़ा समझा और अपने हाथ काट डाले तथा बोल उठीं : अल्लाह की पनाह! यह मनुष्य नहीं है। यह तो कोई सम्मानित फ़रिश्ता है।"},{"a":32,"ar":"قَالَتْ فَذَٰلِكُنَّ ٱلَّذِى لُمْتُنَّنِى فِيهِ ۖ وَلَقَدْ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ فَٱسْتَعْصَمَ ۖ وَلَئِن لَّمْ يَفْعَلْ مَآ ءَامُرُهُۥ لَيُسْجَنَنَّ وَلَيَكُونًا مِّنَ ٱلصَّـٰغِرِينَ","en":"She said, \"That is the one about whom you blamed me. And I certainly sought to seduce him, but he firmly refused; and if he will not do what I order him, he will surely be imprisoned and will be of those debased.\"","ur":"تب زلیخا نے کہا یہ وہی ہے جس کے بارے میں تم مجھے طعنے دیتی تھیں۔ اور بےشک میں نے اس کو اپنی طرف مائل کرنا چاہا مگر یہ بچا رہا۔ اور اگر یہ وہ کام نہ کرے گا جو میں اسے کہتی ہوں تو قید کردیا جائے گا اور ذلیل ہوگا","hi":"वह बोली : यह वही है, जिसके बारे में तुम मेरी निंदा कर रही थीं। वास्तव में, मैंने ही उसे रिझाया था, मगर वह बच निकला। और यदि वह मेरी बात न मानेगा, तो अवश्य ही बंदी बना दिया जाएगा और अवश्य ही अपमानित होगा।"},{"a":33,"ar":"قَالَ رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ ۖ وَإِلَّا تَصْرِفْ عَنِّى كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ٱلْجَـٰهِلِينَ","en":"He said, \"My Lord, prison is more to my liking than that to which they invite me. And if You do not avert from me their plan, I might incline toward them and [thus] be of the ignorant.\"","ur":"یوسف نے دعا کی کہ پروردگار جس کام کی طرف یہ مجھے بلاتی ہیں اس کی نسبت مجھے قید پسند ہے۔ اور اگر تو مجھ سے ان کے فریب کو نہ ہٹائے گا تو میں ان کی طرف مائل ہوجاؤں گا اور نادانوں میں داخل ہوجاؤں گا","hi":"यूसुफ़ ने प्रार्थना की : ऐ मेरे पालनहार! मुझे क़ैद उससे अधिक प्रिय है, जिसकी ओर ये औरतें मुझे बुला रही हैं। और यदि तूने मुझसे इनके छल को दूर नहीं किया, तो मैं इनकी ओर झुक जाऊँगा और अज्ञानियों में से हो जाऊँगा।"},{"a":34,"ar":"فَٱسْتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنْهُ كَيْدَهُنَّ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ","en":"So his Lord responded to him and averted from him their plan. Indeed, He is the Hearing, the Knowing.","ur":"تو خدا نے ان کی دعا قبول کرلی اور ان سے عورتوں کا مکر دفع کر دیا۔ بےشک وہ سننے (اور) جاننے والا ہے","hi":"तो उसके पालनहार ने उसकी प्रार्थना स्वीकार कर ली और उससे उनके छल को दूर कर दिया। निःसंदेह वह बड़ा सुनने वाला, बड़ा जानने वाला है।"},{"a":35,"ar":"ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْـَٔايَـٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍ","en":"Then it appeared to them after they had seen the signs that he [i.e., al-ʿAzeez] should surely imprison him for a time.","ur":"پھر باوجود اس کے کہ وہ لوگ نشان دیکھ چکے تھے ان کی رائے یہی ٹھہری کہ کچھ عرصہ کے لیے ان کو قید ہی کردیں","hi":"फिर उन लोगों ने निशानियाँ देख लेने के बाद यही उचित समझा कि उस (यूसुफ़) को एक अवधि तक के लिए जेल में रखें।"},{"a":36,"ar":"وَدَخَلَ مَعَهُ ٱلسِّجْنَ فَتَيَانِ ۖ قَالَ أَحَدُهُمَآ إِنِّىٓ أَرَىٰنِىٓ أَعْصِرُ خَمْرًا ۖ وَقَالَ ٱلْـَٔاخَرُ إِنِّىٓ أَرَىٰنِىٓ أَحْمِلُ فَوْقَ رَأْسِى خُبْزًا تَأْكُلُ ٱلطَّيْرُ مِنْهُ ۖ نَبِّئْنَا بِتَأْوِيلِهِۦٓ ۖ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ","en":"And there entered the prison with him two young men. One of them said, \"Indeed, I have seen myself [in a dream] pressing [grapes for] wine.\" The other said, \"Indeed, I have seen myself carrying upon my head [some] bread, from which the birds were eating. Inform us of its interpretation; indeed, we see you to be of those who do good.\"","ur":"اور ان کے ساتھ دو اور جوان بھی داخل زندان ہوئے۔ ایک نے ان میں سے کہا کہ (میں نے خواب دیکھا ہے) دیکھتا (کیا) ہوں کہ شراب (کے لیے انگور) نچوڑ رہا ہوں۔ دوسرے نے کہا کہ (میں نے بھی خواب دیکھا ہے) میں یہ دیکھتا ہوں کہ اپنے سر پر روٹیاں اٹھائے ہوئے ہوں اور جانور ان میں سے کھا رہے (ہیں تو) ہمیں ان کی تعبیر بتا دیجیئے کہ ہم تمہیں نیکوکار دیکھتے ہیں","hi":"और क़ैदखाने में उसके साथ दो युवक दाख़िल हुए। उनमें से एक ने कहा : मैंने स्वप्न देखा है कि शराब निचोड़ रहा हूँ। और दूसरे ने कहा : मैंने स्वप्न देखा है कि अपने सिर के ऊपर रोटी उठाए हुए हूँ, जिसमें से पक्षी खा रहे हैं। हमें इसका अर्थ बता दीजिए। हम देख रहे हैं कि आप सदाचारियों में से हैं।"},{"a":37,"ar":"قَالَ لَا يَأْتِيكُمَا طَعَامٌ تُرْزَقَانِهِۦٓ إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِهِۦ قَبْلَ أَن يَأْتِيَكُمَا ۚ ذَٰلِكُمَا مِمَّا عَلَّمَنِى رَبِّىٓ ۚ إِنِّى تَرَكْتُ مِلَّةَ قَوْمٍ لَّا يُؤْمِنُونَ بِٱللَّهِ وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَـٰفِرُونَ","en":"He said, \"You will not receive food that is provided to you except that I will inform you of its interpretation before it comes to you. That is from what my Lord has taught me. Indeed, I have left the religion of a people who do not believe in Allāh, and they, in the Hereafter, are disbelievers.","ur":"یوسف نے کہا کہ جو کھانا تم کو ملنے والا ہے وہ آنے نہیں پائے گا کہ میں اس سے پہلے تم کو اس کی تعبیر بتادوں گا۔ یہ ان (باتوں) میں سے ہے جو میرے پروردگار نے مجھے سکھائی ہیں جو لوگ خدا پر ایمان نہیں لاتے اور روز آخرت سے انکار کرتے ہیں میں ان کا مذہب چھوڑے ہوئے ہوں","hi":"यूसुफ़ ने कहा : तुम दोनों के पास जो भोजन आता है, उसके तुम्हारे पास आने से पहले ही मैं तुम्हें उसकी हक़ीक़त बता दूँगा; यह उन बातों में से है, जो मेरे पालनहार ने मुझे सिखाई हैं। मैंने उन लोगों का धर्म त्याग दिया है, जो अल्लाह पर ईमान नहीं रखते और जो आख़िरत का इनकार करने वाले हैं।"},{"a":38,"ar":"وَٱتَّبَعْتُ مِلَّةَ ءَابَآءِىٓ إِبْرَٰهِيمَ وَإِسْحَـٰقَ وَيَعْقُوبَ ۚ مَا كَانَ لَنَآ أَن نُّشْرِكَ بِٱللَّهِ مِن شَىْءٍ ۚ ذَٰلِكَ مِن فَضْلِ ٱللَّهِ عَلَيْنَا وَعَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ","en":"And I have followed the religion of my fathers, Abraham, Isaac and Jacob. And it was not for us to associate anything with Allāh. That is from the favor of Allāh upon us and upon the people, but most of the people are not grateful.","ur":"اور اپنے باپ دادا ابراہیم اور اسحاق اور یعقوب کے مذہب پر چلتا ہوں۔ ہمیں شایاں نہیں ہے کہ کسی چیز کو خدا کے ساتھ شریک بنائیں۔ یہ خدا کا فضل ہے ہم پر بھی اور لوگوں پر بھی ہے لیکن اکثر لوگ شکر نہیں کرتے","hi":"और मैंने अपने बाप-दादाओं; इबराहीम, इसह़ाक़ और याक़ूब के धर्म का अनुसरण किया है। हमारे लिए वैध नहीं कि हम किसी चीज़ को अल्लाह का साझी बनाएँ। यह हमपर और लोगों पर अल्लाह की कृपा है। लेकिन अधिकतर लोग शुक्रिया अदा नहीं करते।"},{"a":39,"ar":"يَـٰصَـٰحِبَىِ ٱلسِّجْنِ ءَأَرْبَابٌ مُّتَفَرِّقُونَ خَيْرٌ أَمِ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ","en":"O [my] two companions of prison, are separate lords better or Allāh, the One, the Prevailing?","ur":"میرے جیل خانے کے رفیقو! بھلا کئی جدا جدا آقا اچھے یا (ایک) خدائے یکتا وغالب؟","hi":"ऐ मेरे जेल के दोनों साथियो! क्या अलग-अलग अनेक पूज्य बेहतर हैं या एक प्रभुत्वशाली अल्लाह?"},{"a":40,"ar":"مَا تَعْبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسْمَآءً سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَـٰنٍ ۚ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۚ أَمَرَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ","en":"You worship not besides Him except [mere] names you have named them, you and your fathers, for which Allāh has sent down no evidence. Legislation is not but for Allāh. He has commanded that you worship not except Him. That is the correct religion, but most of the people do not know.","ur":"جن چیزوں کی تم خدا کے سوا پرستش کرتے ہو وہ صرف نام ہی نام ہیں جو تم نے اور تمہارے باپ دادا نے رکھ لیے ہیں۔ خدا نے ان کی کوئی سند نازل نہیں کی۔ (سن رکھو کہ) خدا کے سوا کسی کی حکومت نہیں ہے۔ اس نے ارشاد فرمایا ہے کہ اس کے سوا کسی کی عبادت نہ کرو۔ یہی سیدھا دین ہے لیکن اکثر لوگ نہیں جانتے","hi":"तुम अल्लाह के सिवा जिनकी इबादत (पूजा) करते हो, वे केवल नाम हैं, जो तुमने और तुम्हारे बाप-दादा ने रख लिए हैं। अल्लाह ने उनका कोई प्रमाण नहीं उतारा है। आदेश तो केवल अल्लाह का चलता है। उसने आदेश दिया है कि तुम एकमात्र उसी की इबादत (उपासना) करो। यही सीधा धर्म है। परन्तु अधिकतर लोग नहीं जानते।"},{"a":41,"ar":"يَـٰصَـٰحِبَىِ ٱلسِّجْنِ أَمَّآ أَحَدُكُمَا فَيَسْقِى رَبَّهُۥ خَمْرًا ۖ وَأَمَّا ٱلْـَٔاخَرُ فَيُصْلَبُ فَتَأْكُلُ ٱلطَّيْرُ مِن رَّأْسِهِۦ ۚ قُضِىَ ٱلْأَمْرُ ٱلَّذِى فِيهِ تَسْتَفْتِيَانِ","en":"O two companions of prison, as for one of you, he will give drink to his master of wine; but as for the other, he will be crucified, and the birds will eat from his head. The matter has been decreed about which you both inquire.\"","ur":"میرے جیل خانے کے رفیقو! تم میں سے ایک (جو پہلا خواب بیان کرنے والا ہے وہ) تو اپنے آقا کو شراب پلایا کرے گا اور جو دوسرا ہے وہ سولی دیا جائے گا اور جانور اس کا سر کھا جائیں گے۔ جو امر تم مجھ سے پوچھتے تھے وہ فیصلہ ہوچکا ہے","hi":"ऐ मेरे जेल के दोनों साथियो! तुम दोनो में से एक तो अपने मालिक को शराब पिलाएगा, और रहा दूसरा तो उसे सूली पर चढ़ाया जाएगा, फिर पक्षी उसके सिर में से खाएँगे। जिसके संबंध में तुम दोनों पूछ रहे हो, उसका निर्णय किया जा चुका है।"},{"a":42,"ar":"وَقَالَ لِلَّذِى ظَنَّ أَنَّهُۥ نَاجٍ مِّنْهُمَا ٱذْكُرْنِى عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيْطَـٰنُ ذِكْرَ رَبِّهِۦ فَلَبِثَ فِى ٱلسِّجْنِ بِضْعَ سِنِينَ","en":"And he said to the one whom he knew would go free, \"Mention me before your master.\" But Satan made him forget the mention [to] his master, and he [i.e., Joseph] remained in prison several years.","ur":"اور دونوں شخصوں میں سے جس کی نسبت (یوسف نے) خیال کیا کہ وہ رہائی پا جائے گا اس سے کہا کہ اپنے آقا سے میرا ذکر بھی کرنا لیکن شیطان نے ان کا اپنے آقا سے ذکر کرنا بھلا دیا اور یوسف کئی برس جیل خانے میں رہے","hi":"और (यूसुफ़ ने) उन दोनों में से जिसके बारे में समझा था कि वह रिहा होने वाला है, उससे कहा : अपने मालिक के पास मेरा ज़िक्र करना। परंतु शैतान ने उसे अपने मालिक के पास उसकी चर्चा करने की बात भुला दी। अतः वह (यूसुफ़) कई वर्ष तक जेल ही में रहा।"},{"a":43,"ar":"وَقَالَ ٱلْمَلِكُ إِنِّىٓ أَرَىٰ سَبْعَ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنۢبُلَـٰتٍ خُضْرٍ وَأُخَرَ يَابِسَـٰتٍ ۖ يَـٰٓأَيُّهَا ٱلْمَلَأُ أَفْتُونِى فِى رُءْيَـٰىَ إِن كُنتُمْ لِلرُّءْيَا تَعْبُرُونَ","en":"And [subsequently] the king said, \"Indeed, I have seen [in a dream] seven fat cows being eaten by seven [that were] lean, and seven green spikes [of grain] and others [that were] dry. O eminent ones, explain to me my vision, if you should interpret visions.\"","ur":"اور بادشاہ نے کہا کہ میں (نے خواب دیکھا ہے) دیکھتا (کیا) ہوں کہ سات موٹی گائیں ہیں جن کو سات دبلی گائیں کھا رہی ہیں اور سات خوشے سبز ہیں اور (سات) خشک۔ اے سردارو! اگر تم خوابوں کی تعبیر دے سکتے ہو تو مجھے میرے خواب کی تعبیر بتاؤ","hi":"और (एक दिन) राजा ने कहा : निःसंदेह मैं (सपने में) सात मोटी गायों को देखता हूँ, जिनको सात दुबली गाएँ खा रही हैं और सात हरी बालियाँ हैं और दूसरी सात सूखी हैं। ऐ प्रमुखो! यदि तुम स्वप्न का अर्थ बता सकते हो, तो मुझे मेरे स्वप्न के संबंध में बताओ?"},{"a":44,"ar":"قَالُوٓا۟ أَضْغَـٰثُ أَحْلَـٰمٍ ۖ وَمَا نَحْنُ بِتَأْوِيلِ ٱلْأَحْلَـٰمِ بِعَـٰلِمِينَ","en":"They said, \"[It is but] a mixture of false dreams, and we are not learned in the interpretation of dreams.\"","ur":"انہوں نے کہا یہ تو پریشان سے خواب ہیں۔ اور ہمیں ایسے خوابوں کی تعبیر نہیں آتی","hi":"उन्होंने कहा : ये तो उलझे सपनों का मिश्रण है और हम ऐसे सपनों के अर्थ से अवगत नहीं हैं।"},{"a":45,"ar":"وَقَالَ ٱلَّذِى نَجَا مِنْهُمَا وَٱدَّكَرَ بَعْدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأْوِيلِهِۦ فَأَرْسِلُونِ","en":"But the one who was freed and remembered after a time said, \"I will inform you of its interpretation, so send me forth.\"","ur":"اب وہ شخص جو دونوں قیدیوں میں سے رہائی پا گیا تھا اور جسے مدت کے بعد وہ بات یاد آگئی بول اٹھا کہ میں آپ کو اس کی تعبیر (لا) بتاتا ہوں مجھے (جیل خانے) جانے کی اجازت دے دیجیئے","hi":"और उन दोनों में से जो रिहा हुआ था और उसे एक अवधि के बाद याद आया, उसने कहा : मैं तुम्हें इसका अर्थ बताऊँगा। अतः मुझे भेजो।"},{"a":46,"ar":"يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفْتِنَا فِى سَبْعِ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعِ سُنۢبُلَـٰتٍ خُضْرٍ وَأُخَرَ يَابِسَـٰتٍ لَّعَلِّىٓ أَرْجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمْ يَعْلَمُونَ","en":"[He said], \"Joseph, O man of truth, explain to us about seven fat cows eaten by seven [that were] lean, and seven green spikes [of grain] and others [that were] dry - that I may return to the people [i.e., the king and his court]; perhaps they will know [about you].\"","ur":"(غرض وہ یوسف کے پاس آیا اور کہنے لگا) یوسف اے بڑے سچے (یوسف) ہمیں اس خواب کی تعبیر بتایئے کہ سات موٹی گائیوں کو سات دبلی گائیں کھا رہی ہیں۔ اور سات خوشے سبز ہیں اور سات سوکھے تاکہ میں لوگوں کے پاس واپس جا (کر تعبیر بتاؤں)۔ عجب نہیں کہ وہ (تمہاری قدر) جانیں","hi":"ऐ यूसुफ़! ऐ सत्यवादी! हमें सात मोटी गायों के बारे में बताओ, जिन्हें सात दुबली गाएँ खा रही हैं और सात हरी बालियाँ हैं और सात सूखी, ताकि मैं लोगों के पास वापस जाऊँ, ताकि वे जान लें।"},{"a":47,"ar":"قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًا فَمَا حَصَدتُّمْ فَذَرُوهُ فِى سُنۢبُلِهِۦٓ إِلَّا قَلِيلًا مِّمَّا تَأْكُلُونَ","en":"[Joseph] said, \"You will plant for seven years consecutively; and what you harvest leave in its spikes, except a little from which you will eat.","ur":"انہوں نے کہا کہ تم لوگ سات سال متواتر کھیتی کرتے رہوگے تو جو (غلّہ) کاٹو تو تھوڑے سے غلّے کے سوا جو کھانے میں آئے اسے خوشوں میں ہی رہنے دینا","hi":"यूसुफ़ ने कहा : तुम सात वर्षों तक निरंतर खेती करोगे। चुनाँचे तुम जो (फ़सल) काटो, उसे उसकी बालियों ही में रहने दो सिवाय थोड़ी (मात्रा) के जो तुम खाओ।"},{"a":48,"ar":"ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ سَبْعٌ شِدَادٌ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلًا مِّمَّا تُحْصِنُونَ","en":"Then will come after that seven difficult [years] which will consume what you advanced [i.e., saved] for them, except a little from which you will store.","ur":"پھر اس کے بعد (خشک سالی کے) سات سخت (سال) آئیں گے کہ جو (غلّہ) تم نے جمع کر رکھا ہوگا وہ اس سب کو کھا جائیں گے۔ صرف وہی تھوڑا سا رہ جائے گا جو تم احتیاط سے رکھ چھوڑو گے","hi":"फिर इसके बाद सात कठिन वर्ष आएँगे, जो उसे खा जाएँगे, जो तुमने उनके लिए पहले से इकट्ठा कर रखा होगा, सिवाय उस थोड़े-से हिस्से के जो तुम सुरक्षित कर लोगे।"},{"a":49,"ar":"ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ عَامٌ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعْصِرُونَ","en":"Then will come after that a year in which the people will be given rain and in which they will press [olives and grapes].\"","ur":"پھر اس کے بعد ایک سال آئے گا کہ خوب مینہ برسے گا اور لوگ اس میں رس نچوڑیں گے","hi":"फिर उसके बाद एक ऐसा वर्ष आएगा, जिसमें लोगों पर बारिश होगी तथा वे उसमें (रस) निचोड़ेंगे।"},{"a":50,"ar":"وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦ ۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرْجِعْ إِلَىٰ رَبِّكَ فَسْـَٔلْهُ مَا بَالُ ٱلنِّسْوَةِ ٱلَّـٰتِى قَطَّعْنَ أَيْدِيَهُنَّ ۚ إِنَّ رَبِّى بِكَيْدِهِنَّ عَلِيمٌ","en":"And the king said, \"Bring him to me.\" But when the messenger came to him, [Joseph] said, \"Return to your master and ask him what is the case of the women who cut their hands. Indeed, my Lord is Knowing of their plan.\"","ur":"(یہ تعبیر سن کر) بادشاہ نے حکم دیا کہ یوسف کو میرے پاس لے آؤ۔ جب قاصد ان کے پاس گیا تو انہوں نے کہا کہ اپنے آقا کے پاس واپس جاؤ اور ان سے پوچھو کہ ان عورتوں کا کیا حال ہے جنہوں نے اپنے ہاتھ کاٹ لیے تھے۔ بےشک میرا پروردگار ان کے مکروں سے خوب واقف ہے","hi":"और राजा ने कहा : उसे मेरे पास लाओ। फिर जब दूत यूसुफ़ के पास पहुँचा, तो उन्होंने (उससे) कहा : अपने मालिक के पास वापस जाओ और उससे पूछो कि उन स्त्रियों का क्या मामला है, जिन्होंने अपने हाथ काट लिए थे? निःसंदेह मेरा पालनहार उन स्त्रियों के छल से भली-भाँति अवगत है।"},{"a":51,"ar":"قَالَ مَا خَطْبُكُنَّ إِذْ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِۦ ۚ قُلْنَ حَـٰشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوٓءٍ ۚ قَالَتِ ٱمْرَأَتُ ٱلْعَزِيزِ ٱلْـَٔـٰنَ حَصْحَصَ ٱلْحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِينَ","en":"Said [the king to the women], \"What was your condition when you sought to seduce Joseph?\" They said, \"Perfect is Allāh! We know about him no evil.\" The wife of al-ʿAzeez said, \"Now the truth has become evident. It was I who sought to seduce him, and indeed, he is of the truthful.","ur":"بادشاہ نے عورتوں سے پوچھا کہ بھلا اس وقت کیا ہوا تھا جب تم نے یوسف کو اپنی طرف مائل کرنا چاہا۔ سب بول اٹھیں کہ حاش َللهِ ہم نے اس میں کوئی برائی معلوم نہیں کی۔ عزیز کی عورت نے کہا اب سچی بات تو ظاہر ہو ہی گئی ہے۔ (اصل یہ ہے کہ) میں نے اس کو اپنی طرف مائل کرنا چاہا تھا اور بےشک وہ سچا ہے","hi":"राजा ने (उन स्त्रियों से) पूछा : तुम्हारा क्या मामला था, जब तुमने यूसुफ़ के मन को रिझाया था? उन्होंने कहा : अल्लाह की पनाह! हमने उसमें कोई बुराई नहीं देखी। तब अज़ीज़ की पत्नी बोल उठी : अब सत्य खूब उजागर हो गया। मैंने ही उसके मन को रिझाया था और निःसंदेह वह सच्चा में से है।"},{"a":52,"ar":"ذَٰلِكَ لِيَعْلَمَ أَنِّى لَمْ أَخُنْهُ بِٱلْغَيْبِ وَأَنَّ ٱللَّهَ لَا يَهْدِى كَيْدَ ٱلْخَآئِنِينَ","en":"That is so he [i.e., al-ʿAzeez] will know that I did not betray him in [his] absence and that Allāh does not guide the plan of betrayers.","ur":"(یوسف نے کہا کہ میں نے) یہ بات اس لیے (پوچھی ہے) کہ عزیز کو یقین ہوجائے کہ میں نے اس کی پیٹھ پیچھے اس کی (امانت میں خیانت نہیں کی) اور خدا خیانت کرنے والوں کے مکروں کو روبراہ نہیں کرتا","hi":"(मैंने) यह इसलिए किया, ताकि वह जान ले कि मैंने उसकी अनुपस्थिति में उसके साथ विश्वासघात नहीं किया और निःसंदेह अल्लाह विश्वासघातियों के चाल को (सफलता का) मार्ग नहीं दिखाता।"},{"a":53,"ar":"۞ وَمَآ أُبَرِّئُ نَفْسِىٓ ۚ إِنَّ ٱلنَّفْسَ لَأَمَّارَةٌۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّىٓ ۚ إِنَّ رَبِّى غَفُورٌ رَّحِيمٌ","en":"And I do not acquit myself. Indeed, the soul is a persistent enjoiner of evil, except those upon which my Lord has mercy. Indeed, my Lord is Forgiving and Merciful.\"","ur":"اور میں اپنے تئیں پاک صاف نہیں کہتا کیونکہ نفس امارہ (انسان کو) برائی سکھاتا رہتا ہے۔ مگر یہ کہ میرا پروردگار رحم کرے گا۔ بےشک میرا پروردگار بخشنے والا مہربان ہے","hi":"और मैं खुद को बरी नहीं करती, निःसंदेह मन तो बुराई का बहुत आदेश देने वाला है, सिवाय उसके जिसपर मेरा पालनहार दया करे। निःसंदेह मेरा पालनहार अति क्षमाशील, अत्यंत दयावान् है।"},{"a":54,"ar":"وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦٓ أَسْتَخْلِصْهُ لِنَفْسِى ۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلْيَوْمَ لَدَيْنَا مَكِينٌ أَمِينٌ","en":"And the king said, \"Bring him to me; I will appoint him exclusively for myself.\" And when he spoke to him, he said, \"Indeed, you are today established [in position] and trusted.\"","ur":"بادشاہ نے حکم دیا کہ اسے میرے پاس لاؤ میں اسے اپنا مصاحب خاص بناؤں گا۔ پھر جب ان سے گفتگو کی تو کہا کہ آج سے تم ہمارے ہاں صاحب منزلت اور صاحبِ اعتبار ہو","hi":"और राजा ने कहा : उसे मेरे पास लाओ, उसे मैं अपने लिए विशेष कर लूँ और जब (राजा ने) उन (यूसुफ़) से बात की, तो कहा : निःसंदेह आप आज हमारे यहाँ पदाधिकारी, विश्वसनीय हैं।"},{"a":55,"ar":"قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ ۖ إِنِّى حَفِيظٌ عَلِيمٌ","en":"[Joseph] said, \"Appoint me over the storehouses of the land. Indeed, I will be a knowing guardian.\"","ur":"(یوسف نے) کہا مجھے اس ملک کے خزانوں پر مقرر کر دیجیئے کیونکہ میں حفاظت بھی کرسکتا ہوں اور اس کام سے واقف ہوں","hi":"(यूसुफ़) ने कहा : मुझे इस देश के ख़ज़ानों पर नियुक्त कर दीजिए। निःसंदेह मैं संरक्षण करने वाला, बड़ा जानकार हूँ।"},{"a":56,"ar":"وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَآءُ ۚ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَآءُ ۖ وَلَا نُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ","en":"And thus We established Joseph in the land to settle therein wherever he willed. We touch with Our mercy whom We will, and We do not allow to be lost the reward of those who do good.","ur":"اس طرح ہم نے یوسف کو ملک (مصر) میں جگہ دی اور وہ اس ملک میں جہاں چاہتے تھے رہتے تھے۔ ہم اپنی رحمت جس پر چاہتے ہیں کرتے ہیں اور نیکوکاروں کے اجر کو ضائع نہیں کرتے","hi":"और इसी प्रकार, हमने यूसुफ़ को उस धरती (देश) में अधिकार प्रदान किया। वह उसमें जहाँ चाहते, रहते थे। हम अपनी दया जिसे चाहें, प्रदान करते हैं और हम सदाचारियों का प्रतिफल नष्ट नहीं करते।"},{"a":57,"ar":"وَلَأَجْرُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ","en":"And the reward of the Hereafter is better for those who believed and were fearing Allāh.","ur":"اور جو لوگ ایمان لائے اور ڈرتے رہے ان کے لیے آخرت کا اجر بہت بہتر ہے","hi":"और निश्चय आख़िरत का बदला उन लोगों के लिए अधिक बेहतर है, जो ईमान लाए और अल्लाह से डरते रहे।"},{"a":58,"ar":"وَجَآءَ إِخْوَةُ يُوسُفَ فَدَخَلُوا۟ عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُۥ مُنكِرُونَ","en":"And the brothers of Joseph came [seeking food], and they entered upon him; and he recognized them, but he was to them unknown.","ur":"اور یوسف کے بھائی (کنعان سے مصر میں غلّہ خریدنے کے لیے) آئے تو یوسف کے پاس گئے تو یوسف نے ان کو پہچان لیا اور وہ ان کو نہ پہچان سکے","hi":"और यूसुफ़ के भाई आए, फिर वे उसके पास गए, तो उसने उन्हें पहचान लिया, जबकि वे उसे पहचान नहीं सके।"},{"a":59,"ar":"وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ٱئْتُونِى بِأَخٍ لَّكُم مِّنْ أَبِيكُمْ ۚ أَلَا تَرَوْنَ أَنِّىٓ أُوفِى ٱلْكَيْلَ وَأَنَا۠ خَيْرُ ٱلْمُنزِلِينَ","en":"And when he had furnished them with their supplies, he said, \"Bring me a brother of yours from your father. Do you not see that I give full measure and that I am the best of accommodators?","ur":"جب یوسف نے ان کے لیے ان کا سامان تیار کر دیا تو کہا کہ (پھر آنا تو) جو باپ کی طرف سے تمہارا ایک اور بھائی ہے اسے بھی میرے پاس لیتے آنا۔ کیا تم نہیں دیکھتے کہ میں ناپ بھی پوری پوری دیتا ہوں اور مہمانداری بھی خوب کرتا ہوں","hi":"और जब उनका सामान तैयार कर दिया, तो कहा : मेरे पास अपने उस भाई को लेकर आना जो तुम्हारे बाप की ओर से है। क्या तुम नहीं देखते कि मैं पूरी माप देता हूँ तथा मैं उत्तम अतिथि-सत्कार करने वाला हूँ?"},{"a":60,"ar":"فَإِن لَّمْ تَأْتُونِى بِهِۦ فَلَا كَيْلَ لَكُمْ عِندِى وَلَا تَقْرَبُونِ","en":"But if you do not bring him to me, no measure will there be [hereafter] for you from me, nor will you approach me.\"","ur":"اور اگر تم اسے میرے پاس نہ لاؤ گے تو نہ تمہیں میرے ہاں سے غلّہ ملے گا اور نہ تم میرے پاس ہی آسکو گے","hi":"फिर यदि तुम उसे मेरे पास न लाए, तो तुम्हारे लिए मेरे पास न कोई माप होगा और न तुम मेरे पास आना।"},{"a":61,"ar":"قَالُوا۟ سَنُرَٰوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَـٰعِلُونَ","en":"They said, \"We will attempt to dissuade his father from [keeping] him, and indeed, we will do [it].\"","ur":"انہوں نے کہا کہ ہم اس کے بارے میں اس کے والد سے تذکرہ کریں گے اور ہم (یہ کام) کرکے رہیں گے","hi":"वे बोले : हम उसके पिता को इसके लिए राज़ी करने का पूरा प्रयास करेंगे और हम अवश्य ऐसा करने वाले हैं।"},{"a":62,"ar":"وَقَالَ لِفِتْيَـٰنِهِ ٱجْعَلُوا۟ بِضَـٰعَتَهُمْ فِى رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَآ إِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ","en":"And [Joseph] said to his servants, \"Put their merchandise into their saddlebags so they might recognize it when they have gone back to their people that perhaps they will [again] return.\"","ur":"(اور یوسف نے) اپنے خدام سے کہا کہ ان کا سرمایہ (یعنی غلّے کی قیمت) ان کے شلیتوں میں رکھ دو عجب نہیں کہ جب یہ اپنے اہل وعیال میں جائیں تو اسے پہچان لیں (اور) عجب نہیں کہ پھر یہاں آئیں","hi":"और यूसुफ़ ने अपने सेवकों को आदेश दिया : उनका मूलधन उनकी बोरियों में रख दो। ताकि वे उसे पहचान लें, जब वे अपने परिजनों की ओर वापस जाएँ, शायद वे फिर आ जाएँ।"},{"a":63,"ar":"فَلَمَّا رَجَعُوٓا۟ إِلَىٰٓ أَبِيهِمْ قَالُوا۟ يَـٰٓأَبَانَا مُنِعَ مِنَّا ٱلْكَيْلُ فَأَرْسِلْ مَعَنَآ أَخَانَا نَكْتَلْ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ","en":"So when they returned to their father, they said, \"O our father, [further] measure has been denied to us, so send with us our brother [that] we will be given measure. And indeed, we will be his guardians.\"","ur":"جب وہ اپنے باپ کے پاس واپس گئے تو کہنے لگے کہ ابّا (جب تک ہم بنیامین کو ساتھ نہ لے جائیں) ہمارے لیے غلّے کی بندش کر دی گئی ہے تو ہمارے ساتھ ہمارے بھائی کو بھیج دے تاکہ ہم پھر غلّہ لائیں اور ہم اس کے نگہبان ہیں","hi":"फिर जब वे अपने पिता के पास लौटे, तो कहा : ऐ हमारे पिता! हमसे (भविष्य में) माप रोक लिया गया है। अतः हमारे साथ हमारे भाई को भेजें कि हम माप (ग़ल्ला) लेकर आएँ और निःसंदेह हम उसकी अवश्य रक्षा करने वाले हैं।"},{"a":64,"ar":"قَالَ هَلْ ءَامَنُكُمْ عَلَيْهِ إِلَّا كَمَآ أَمِنتُكُمْ عَلَىٰٓ أَخِيهِ مِن قَبْلُ ۖ فَٱللَّهُ خَيْرٌ حَـٰفِظًا ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ","en":"He said, \"Should I entrust you with him except [under coercion] as I entrusted you with his brother before? But Allāh is the best guardian, and He is the most merciful of the merciful.\"","ur":"(یعقوب نے) کہا کہ میں اس کے بارے میں تمہارا اعتبار نہیں کرتا مگر ویسا ہی جیسا اس کے بھائی کے بارے میں کیا تھا۔ سو خدا ہی بہتر نگہبان ہے۔ اور وہ سب سے زیادہ رحم کرنے والا ہے","hi":"(याक़ूब अलैहिस्सलाम) ने कहा : क्या मैं इसके बारे में तुम्हारा वैसे ही विश्वास करूँ, जैसे इससे पहले इसके भाई (यूसुफ़) के बारे में तुम्हारा विश्वास किया था? तो अल्लाह ही बेहतर संरक्षण करने वाला है और वह सब दया करने वालों से अधिक दया करने वाला है।"},{"a":65,"ar":"وَلَمَّا فَتَحُوا۟ مَتَـٰعَهُمْ وَجَدُوا۟ بِضَـٰعَتَهُمْ رُدَّتْ إِلَيْهِمْ ۖ قَالُوا۟ يَـٰٓأَبَانَا مَا نَبْغِى ۖ هَـٰذِهِۦ بِضَـٰعَتُنَا رُدَّتْ إِلَيْنَا ۖ وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍ ۖ ذَٰلِكَ كَيْلٌ يَسِيرٌ","en":"And when they opened their baggage, they found their merchandise returned to them. They said, \"O our father, what [more] could we desire? This is our merchandise returned to us. And we will obtain supplies [i.e., food] for our family and protect our brother and obtain an increase of a camel's load; that is an easy measurement.\"","ur":"اور جب انہوں نے اپنا اسباب کھولا تو دیکھا کہ ان کا سرمایہ واپس کر دیا گیا ہے۔ کہنے لگے ابّا ہمیں (اور) کیا چاہیئے (دیکھیے) یہ ہماری پونجی بھی ہمیں واپس کر دی گئی ہے۔ اب ہم اپنے اہل وعیال کے لیے پھر غلّہ لائیں گے اور اپنے بھائی کی نگہبانی کریں گے اور ایک بار شتر زیادہ لائیں گے (کہ) یہ غلّہ جو ہم لائے ہیں تھوڑا ہے","hi":"और जब उन्होंने अपना सामान खोला, तो देखा कि उनका मूलधन उन्हें लौटा दिया गया है। वे बोल उठे : पिता जी! हमें और क्या चाहिए? यह हमारा धन हमें वापस कर दिया गया है। (अब) हम अपने घर वालों के लिए ग़ल्ला लाएँगे और अपने भाई की रक्षा करेंगे और एक ऊँट के बोझभर (ग़ल्ला) अधिक लाएँगे। यह माप तो बहुत आसान है।"},{"a":66,"ar":"قَالَ لَنْ أُرْسِلَهُۥ مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِقًا مِّنَ ٱللَّهِ لَتَأْتُنَّنِى بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمْ ۖ فَلَمَّآ ءَاتَوْهُ مَوْثِقَهُمْ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ","en":"[Jacob] said, \"Never will I send him with you until you give me a promise [i.e., oath] by Allāh that you will bring him [back] to me, unless you should be surrounded [i.e., overcome by enemies].\" And when they had given their promise, he said, \"Allāh, over what we say, is Entrusted.\"","ur":"(یعقوب نے) کہا جب تک تم خدا کا عہد نہ دو کہ اس کو میرے پاس (صحیح سالم) لے آؤ گے میں اسے ہرگز تمہارے ساتھ نہیں بھیجنے کا۔ مگر یہ کہ تم گھیر لیے جاؤ (یعنی بےبس ہوجاؤ تو مجبوری ہے) جب انہوں نے ان سے عہد کرلیا تو (یعقوب نے) کہا کہ جو قول وقرار ہم کر رہے ہیں اس کا خدا ضامن ہے","hi":"उस (याक़ूब) ने कहा : मैं उसे तुम्हारे साथ हरगिज़ नहीं भेजूँगा, यहाँ तक कि तुम मुझसे अल्लाह के नाम पर प्रतिज्ञा करो कि उसे मेरे पास अवश्य लाओगे, सिवाय इसके कि तुम (सब) को घेर लिया जाए। फिर जब उन्होंने उसे अपना दृढ़ वचन दिया, तो उस (याक़ूब) ने कहा : हम जो कुछ कह रहे हैं, उसपर अल्लाह निरीक्षक (गवाह) है।"},{"a":67,"ar":"وَقَالَ يَـٰبَنِىَّ لَا تَدْخُلُوا۟ مِنۢ بَابٍ وَٰحِدٍ وَٱدْخُلُوا۟ مِنْ أَبْوَٰبٍ مُّتَفَرِّقَةٍ ۖ وَمَآ أُغْنِى عَنكُم مِّنَ ٱللَّهِ مِن شَىْءٍ ۖ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَعَلَيْهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ","en":"And he said, \"O my sons, do not enter from one gate but enter from different gates; and I cannot avail you against [the decree of] Allāh at all. The decision is only for Allāh; upon Him I have relied, and upon Him let those who would rely [indeed] rely.\"","ur":"اور ہدایت کی کہ بیٹا ایک ہی دروازے سے داخل نہ ہونا بلکہ جدا جدا دروازوں سے داخل ہونا۔ اور میں خدا کی تقدیر کو تم سے نہیں روک سکتا۔ بےشک حکم اسی کا ہے میں اسی پر بھروسہ رکھتا ہوں۔ اور اہلِ توکل کو اسی پر بھروسہ رکھنا چاہیئے","hi":"और (जब वे जाने लगे) तो याक़ूब ने कहा : ऐ मेरे बेटो! तुम एक ही द्वार से (मिस्र में) प्रवेश न करना, बल्कि अलग-अलग द्वारों से प्रवेश करना। और मैं तुम्हें अल्लाह की ओर से (आने वाली) किसी चीज़ से नहीं बचा सकता। आदेश तो केवल अल्लाह का चलता है। मैंने उसी पर भरोसा किया और भरोसा करने वालों को उसी पर भरोसा करना चाहिए।"},{"a":68,"ar":"وَلَمَّا دَخَلُوا۟ مِنْ حَيْثُ أَمَرَهُمْ أَبُوهُم مَّا كَانَ يُغْنِى عَنْهُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِلَّا حَاجَةً فِى نَفْسِ يَعْقُوبَ قَضَىٰهَا ۚ وَإِنَّهُۥ لَذُو عِلْمٍ لِّمَا عَلَّمْنَـٰهُ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ","en":"And when they entered from where their father had ordered them, it did not avail them against Allāh at all except [it was] a need [i.e., concern] within the soul of Jacob, which he satisfied. And indeed, he was a possessor of knowledge because of what We had taught him, but most of the people do not know.","ur":"اور جب وہ ان ان مقامات سے داخل ہوئے جہاں جہاں سے (داخل ہونے کے لیے) باپ نے ان سے کہا تھا تو وہ تدبیر خدا کے حکم کو ذرا بھی نہیں ٹال سکتی تھی ہاں وہ یعقوب کے دل کی خواہش تھی جو انہوں نے پوری کی تھی۔ اور بےشک وہ صاحبِ علم تھے کیونکہ ہم نے ان کو علم سکھایا تھا لیکن اکثر لوگ نہیں جانتے","hi":"और जब उन्होंने (मिस्र में उस तरह) प्रवेश किया, जैसे उनके पिता ने उन्हें आदेश दिया था, वह उन्हें अल्लाह की ओर से आने वाली किसी चीज़ से नहीं बचा सकते थे; परंतु याक़ूब के दिल में एक इच्छा थी, जो उन्होंने पूरी कर ली। और निःसंदेह वह बड़े ज्ञानवान थे, इस वजह से कि हमने उन्हें ज्ञान प्रदान किया था। लेकिन अधिकांश लोग नहीं जानते।"},{"a":69,"ar":"وَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَخَاهُ ۖ قَالَ إِنِّىٓ أَنَا۠ أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَعْمَلُونَ","en":"And when they entered upon Joseph, he took his brother to himself; he said, \"Indeed, I am your brother, so do not despair over what they used to do [to me].\"","ur":"اور جب وہ لوگ یوسف کے پاس پہنچے تو یوسف نے اپنے حقیقی بھائی کو اپنے پاس جگہ دی اور کہا کہ میں تمہارا بھائی ہوں تو جو سلوک یہ (ہمارے ساتھ) کرتے رہے ہیں اس پر افسوس نہ کرنا","hi":"और जब वे यूसुफ़ के पास प्रवेश किए, तो उन्होंने अपने भाई को अपने पास जगह दी।(और) कहा : निःसंदेह मैं तुम्हारा भाई (यूसुफ़) हूँ। अतः जो (दुर्व्यवहार) वे करते रहे हैं उसपर दुःखी न हो।"},{"a":70,"ar":"فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ ٱلسِّقَايَةَ فِى رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلْعِيرُ إِنَّكُمْ لَسَـٰرِقُونَ","en":"So when he had furnished them with their supplies, he put the [gold measuring] bowl into the bag of his brother. Then an announcer called out, \"O caravan, indeed you are thieves.\"","ur":"جب ان کا اسباب تیار کر دیا تو اپنے بھائی کے شلیتے میں گلاس رکھ دیا اور پھر (جب وہ آبادی سے باہر نکل گئے تو) ایک پکارنے والے نے آواز دی کہ قافلے والو تم تو چور ہو","hi":"फिर जब उसने उन्हें उनके सामान के साथ तैयार कर दिया, तो (अनाज) मापने का बर्तन अपने भाई के सामान में रख दिया। फिर एक पुकारने वाले ने पुकारा : ऐ क़ाफ़िले वालो! निःसंदेह तुम निश्चय चोर हो!"},{"a":71,"ar":"قَالُوا۟ وَأَقْبَلُوا۟ عَلَيْهِم مَّاذَا تَفْقِدُونَ","en":"They said while approaching them, \"What is it you are missing?\"","ur":"وہ ان کی طرف متوجہ ہو کر کہنے لگے تمہاری کیا چیز کھوئی گئی ہے","hi":"वे उनकी ओर मुतवज्जेह होकर बोले : तुम्हारी क्या चीज़ खो गई है?"},{"a":72,"ar":"قَالُوا۟ نَفْقِدُ صُوَاعَ ٱلْمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمْلُ بَعِيرٍ وَأَنَا۠ بِهِۦ زَعِيمٌ","en":"They said, \"We are missing the measure of the king. And for he who produces it is [the reward of] a camel's load, and I am responsible for it.\"","ur":"وہ بولے کہ بادشاہ (کے پانی پینے) کا گلاس کھویا گیا ہے اور جو شخص اس کو لے آئے اس کے لیے ایک بار شتر (انعام) اور میں اس کا ضامن ہوں","hi":"उन्होंने कहा : हमें राजा का मापक नहीं मिल रहा है। और जो उसे ले आए, उसके लिए एक ऊँट का बोझ (ग़ल्ला) है और मैं उसके लिए गारंटी देता हूँ।"},{"a":73,"ar":"قَالُوا۟ تَٱللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِى ٱلْأَرْضِ وَمَا كُنَّا سَـٰرِقِينَ","en":"They said, \"By Allāh, you have certainly known that we did not come to cause corruption in the land, and we have not been thieves.\"","ur":"وہ کہنے لگے کہ خدا کی قسم تم کو معلوم ہے کہ ہم (اس) ملک میں اس لیے نہیں آئے کہ خرابی کریں اور نہ ہم چوری کیا کرتے ہیں","hi":"उन्होंने कहा : अल्लाह की क़सम! निश्चय तुम जान चुके हो कि हम इस देश में बिगाड़ पैदा करने नहीं आए हैं और न हम कभी चोर थे।"},{"a":74,"ar":"قَالُوا۟ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمْ كَـٰذِبِينَ","en":"They [the accusers] said, \"Then what would be its recompense if you should be liars?\"","ur":"بولے کہ اگر تم جھوٹے نکلے (یعنی چوری ثابت ہوئی) تو اس کی سزا کیا","hi":"उन लोगों ने कहा : फिर उसका क्या दंड है, यदि तुम झूठे निकले?"},{"a":75,"ar":"قَالُوا۟ جَزَٰٓؤُهُۥ مَن وُجِدَ فِى رَحْلِهِۦ فَهُوَ جَزَٰٓؤُهُۥ ۚ كَذَٰلِكَ نَجْزِى ٱلظَّـٰلِمِينَ","en":"[The brothers] said, \"Its recompense is that he in whose bag it is found - he [himself] will be its recompense. Thus do we recompense the wrongdoers.\"","ur":"انہوں نے کہا کہ اس کی سزا یہ ہے کہ جس کے شلیتے میں وہ دستیاب ہو وہی اس کا بدل قرار دیا جائے ہم ظالموں کو یہی سزا دیا کرتے ہیں","hi":"उन्होंने कहा : उसका दंड यह है कि जिसके सामान में वह पाया जाए, वही व्यक्ति उसका दंड है। हम अत्याचारियों को इसी प्रकार दंड देते हैं।"},{"a":76,"ar":"فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسْتَخْرَجَهَا مِن وِعَآءِ أَخِيهِ ۚ كَذَٰلِكَ كِدْنَا لِيُوسُفَ ۖ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِى دِينِ ٱلْمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ نَرْفَعُ دَرَجَـٰتٍ مَّن نَّشَآءُ ۗ وَفَوْقَ كُلِّ ذِى عِلْمٍ عَلِيمٌ","en":"So he began [the search] with their bags before the bag of his brother; then he extracted it from the bag of his brother. Thus did We plan for Joseph. He could not have taken his brother within the religion [i.e., law] of the king except that Allāh willed. We raise in degrees whom We will, but over every possessor of knowledge is one [more] knowing.","ur":"پھر یوسف نے اپنے بھائی کے شلیتے سے پہلے ان کے شلیتوں کو دیکھنا شروع کیا پھر اپنے بھائی کے شلیتے میں سے اس کو نکال لیا۔ اس طرح ہم نے یوسف کے لیے تدبیر کی (ورنہ) بادشاہ کے قانون کے مطابق وہ مشیتِ خدا کے سوا اپنے بھائی کو لے نہیں سکتے تھے۔ ہم جس کے لیے چاہتے ہیں درجے بلند کرتے ہیں۔ اور ہر علم والے سے دوسرا علم والا بڑھ کر ہے","hi":"चुनाँचे उसने अपने (सगे) भाई के थैले से पहले, उनके थैलों की तलाशी शुरू की। फिर उसे अपने भाई के थैले से निकाला। इस प्रकार, हमने यूसुफ़ के लिए उपाय किया। वह राजा के नियम के अनुसार अपने भाई को नहीं रख सकते थे, परंतु यह कि अल्लाह चाहे। हम जिसके चाहते हैं, पद ऊँचे कर देते हैं और प्रत्येक ज्ञानवान से ऊपर एक बड़ा ज्ञानवान है।"},{"a":77,"ar":"۞ قَالُوٓا۟ إِن يَسْرِقْ فَقَدْ سَرَقَ أَخٌ لَّهُۥ مِن قَبْلُ ۚ فَأَسَرَّهَا يُوسُفُ فِى نَفْسِهِۦ وَلَمْ يُبْدِهَا لَهُمْ ۚ قَالَ أَنتُمْ شَرٌّ مَّكَانًا ۖ وَٱللَّهُ أَعْلَمُ بِمَا تَصِفُونَ","en":"They said, \"If he steals - a brother of his has stolen before.\" But Joseph kept it within himself and did not reveal it to them. He said, \"You are worse in position, and Allāh is most knowing of what you describe.\"","ur":"(برادران یوسف نے) کہا کہ اگر اس نے چوری کی ہو تو (کچھ عجب نہیں کہ) اس کے ایک بھائی نے بھی پہلے چوری کی تھی یوسف نے اس بات کو اپنے دل میں مخفی رکھا اور ان پر ظاہر نہ ہونے دیا (اور) کہا کہ تم بڑے بدقماش ہو۔ اور جو تم بیان کرتے ہو خدا اسے خوب جانتا ہے","hi":"उन्होंने कहा : यदि इसने चोरी की है, तो निःसंदेह इससे पहले इसके एक भाई ने भी चोरी की थी। तो यूसुफ़ ने इस बात को अपने दिल ही में रखा और उनके सामने प्रकट नहीं किया। (यूसुफ़ ने अपने मन में) कहा : तुम सबसे बुरे स्थान वाले हो और जो कुछ तुम वर्णन कर रहे हो, अल्लाह उसे सबसे अधिक जानता है।"},{"a":78,"ar":"قَالُوا۟ يَـٰٓأَيُّهَا ٱلْعَزِيزُ إِنَّ لَهُۥٓ أَبًا شَيْخًا كَبِيرًا فَخُذْ أَحَدَنَا مَكَانَهُۥٓ ۖ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ","en":"They said, \"O ʿAzeez, indeed he has a father [who is] an old man, so take one of us in place of him. Indeed, we see you as a doer of good.\"","ur":"وہ کہنے لگے کہ اے عزیز اس کے والد بہت بوڑھے ہیں (اور اس سے بہت محبت رکھتے ہیں) تو (اس کو چھوڑ دیجیےاور) اس کی جگہ ہم میں سے کسی کو رکھ لیجیئے۔ ہم دیکھتے ہیں کہ آپ احسان کرنے والے ہیں","hi":"उन्होंने कहा : ऐ अज़ीज़! इसका एक बहुत बूढ़ा पिता है। इसलिए आप हममें से किसी को इसके स्थान पर रख लीजिए। निःसंदेह हम आपको उपकारी देखते हैं।"},{"a":79,"ar":"قَالَ مَعَاذَ ٱللَّهِ أَن نَّأْخُذَ إِلَّا مَن وَجَدْنَا مَتَـٰعَنَا عِندَهُۥٓ إِنَّآ إِذًا لَّظَـٰلِمُونَ","en":"He said, \"[I seek] the refuge of Allāh [to prevent] that we take except him with whom we found our possession. Indeed, we would then be unjust.\"","ur":"(یوسف نے) کہا کہ خدا پناہ میں رکھے کہ جس شخص کے پاس ہم نے اپنی چیز پائی ہے اس کے سوا کسی اور کو پکڑ لیں ایسا کریں تو ہم (بڑے) بےانصاف ہیں","hi":"यूसुफ़ ने कहा : अल्लाह की शरण चाहते हैं कि हम उसके अतिरिक्त किसी को पकड़ें, जिसके पास हमने अपना सामान पाया है! निश्चय उस समय तो हम अत्याचारी ठहरेंगे।"},{"a":80,"ar":"فَلَمَّا ٱسْتَيْـَٔسُوا۟ مِنْهُ خَلَصُوا۟ نَجِيًّا ۖ قَالَ كَبِيرُهُمْ أَلَمْ تَعْلَمُوٓا۟ أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُم مَّوْثِقًا مِّنَ ٱللَّهِ وَمِن قَبْلُ مَا فَرَّطتُمْ فِى يُوسُفَ ۖ فَلَنْ أَبْرَحَ ٱلْأَرْضَ حَتَّىٰ يَأْذَنَ لِىٓ أَبِىٓ أَوْ يَحْكُمَ ٱللَّهُ لِى ۖ وَهُوَ خَيْرُ ٱلْحَـٰكِمِينَ","en":"So when they had despaired of him, they secluded themselves in private consultation. The eldest of them said, \"Do you not know that your father has taken upon you an oath by Allāh and [that] before you failed in [your duty to] Joseph? So I will never leave [this] land until my father permits me or Allāh decides for me, and He is the best of judges.","ur":"جب وہ اس سے ناامید ہوگئے تو الگ ہو کر صلاح کرنے لگے۔ سب سے بڑے نے کہا کیا تم نہیں جانتے کہ تمہارے والد نے تم سے خدا کا عہد لیا ہے اور اس سے پہلے بھی تم یوسف کے بارے میں قصور کر چکے ہو تو جب تک والد صاحب مجھے حکم نہ دیں میں تو اس جگہ سے ہلنے کا نہیں یا خدا میرے لیے کوئی اور تدبیر کرے۔ اور وہ سب سے بہتر فیصلہ کرنے والا ہے","hi":"फिर जब वे उनसे बिल्कुल निराश हो गए, तो परामर्श करते हुए अलग जा बैठे। उनके बड़े ने कहा : क्या तुम नहीं जानते कि तुम्हारे पिता ने तुमसे अल्लाह को गवाह बनाकर दृढ़ वचन लिया है? और इससे पहले तुमने यूसुफ़ के बारे में जो कोताही की? (अब) मैं इस धरती (मिस्र) से हरगिज़ नहीं हिलूँगा, यहाँ तक कि मेरे पिता मुझे अनुमति प्रदान कर दें, या अल्लाह मेरे लिए फैसला कर दे और वह सब फैसला करने वालों से बेहतर है।"},{"a":81,"ar":"ٱرْجِعُوٓا۟ إِلَىٰٓ أَبِيكُمْ فَقُولُوا۟ يَـٰٓأَبَانَآ إِنَّ ٱبْنَكَ سَرَقَ وَمَا شَهِدْنَآ إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَـٰفِظِينَ","en":"Return to your father and say, 'O our father, indeed your son has stolen, and we did not testify except to what we knew. And we were not witnesses of the unseen.","ur":"تم سب والد صاحب کے پاس واپس جاؤ اور کہو کہ ابا آپ کے صاحبزادے نے (وہاں جا کر) چوری کی۔ اور ہم نے اپنی دانست کے مطابق آپ سے (اس کے لے آنے کا) عہد کیا تھا مگر ہم غیب کی باتوں کو جاننے اور یاد رکھنے والے تو نہیں تھے","hi":"तुम अपने पिता के पास लौट जाओ और कहो, ऐ हमारे पिता! आपके पुत्र ने चोरी की है और हमने वही कहा, जो हमने जाना और हम ग़ैब जानने वाले नहीं थे।"},{"a":82,"ar":"وَسْـَٔلِ ٱلْقَرْيَةَ ٱلَّتِى كُنَّا فِيهَا وَٱلْعِيرَ ٱلَّتِىٓ أَقْبَلْنَا فِيهَا ۖ وَإِنَّا لَصَـٰدِقُونَ","en":"And ask the city in which we were and the caravan in which we came - and indeed, we are truthful.'\"","ur":"اور جس بستی میں ہم (ٹھہرے) تھے وہاں سے (یعنی اہل مصر سے) اور جس قافلے میں آئے ہیں اس سے دریافت کر لیجیئے اور ہم اس بیان میں بالکل سچے ہیں","hi":"आप उस बस्ती वालों से पूछ लें, जिसमें हम थे और उस क़ाफ़िले से भी, जिसके साथ हम आए हैं। और निःसंदेह हम बिलकुल सच्चे हैं।"},{"a":83,"ar":"قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا ۖ فَصَبْرٌ جَمِيلٌ ۖ عَسَى ٱللَّهُ أَن يَأْتِيَنِى بِهِمْ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ","en":"[Jacob] said, \"Rather, your souls have enticed you to something, so patience is most fitting. Perhaps Allāh will bring them to me all together. Indeed, it is He who is the Knowing, the Wise.\"","ur":"(جب انہوں نے یہ بات یعقوب سے آ کر کہی تو) انہوں نے کہا کہ (حقیقت یوں نہیں ہے) بلکہ یہ بات تم نے اپنے دل سے بنالی ہے تو صبر ہی بہتر ہے۔ عجب نہیں کہ خدا ان سب کو میرے پاس لے آئے۔ بےشک وہ دانا (اور) حکمت والا ہے","hi":"याक़ूब ने कहा : (ऐसा नहीं है), बल्कि तुम्हारे दिलों ने एक बात बना ली है। इसलिए मेरा काम उत्तम सब्र है। आशा है कि अल्लाह उन सब को मेरे पास ले आएगा। निःसंदेह वही सब कुछ जानने वाला, पूर्ण हिकमत वाला है।"},{"a":84,"ar":"وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَـٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبْيَضَّتْ عَيْنَاهُ مِنَ ٱلْحُزْنِ فَهُوَ كَظِيمٌ","en":"And he turned away from them and said, \"Oh, my sorrow over Joseph,\" and his eyes became white from grief, for he was [of that] a suppressor.","ur":"پھر ان کے پاس سے چلے گئے اور کہنے لگے ہائے افسوس یوسف (ہائے افسوس) اور رنج والم میں (اس قدر روئے کہ) ان کی آنکھیں سفید ہوگئیں اور ان کا دل غم سے بھر رہا تھا","hi":"और वह उनसे वापस फिरा और कहा : हाय अफ़सोस, यूसुफ़ की जुदाई पर! और उसकी दोनों आँखें शोक के कारण सफेद हो गईं। तो वह शोक से भरा हुआ था।"},{"a":85,"ar":"قَالُوا۟ تَٱللَّهِ تَفْتَؤُا۟ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ ٱلْهَـٰلِكِينَ","en":"They said, \"By Allāh, you will not cease remembering Joseph until you become fatally ill or become of those who perish.\"","ur":"بیٹے کہنے لگے کہ والله اگر آپ یوسف کو اسی طرح یاد ہی کرتے رہیں گے تو یا تو بیمار ہوجائیں گے یا جان ہی دے دیں گے","hi":"उन्होंने कहा : अल्लाह की क़सम! आप बराबर यूसुफ़ को याद करते रहेंगे, यहाँ तक कि (शोक से) घुल जाएँ या अपना विनाश कर लें।"},{"a":86,"ar":"قَالَ إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ","en":"He said, \"I only complain of my suffering and my grief to Allāh, and I know from Allāh that which you do not know.","ur":"انہوں نے کہا کہ میں اپنے غم واندوہ کا اظہار خدا سے کرتا ہوں۔ اور خدا کی طرف سے وہ باتیں جانتا ہوں جو تم نہیں جانتے","hi":"उन्होंने कहा : मैं तो अपने दुःख तथा शोक की शिकायत केवल अल्लाह से करता हूँ और मैं अल्लाह की ओर से वह (बात) जानता हूँ, जो तुम नहीं जानते।"},{"a":87,"ar":"يَـٰبَنِىَّ ٱذْهَبُوا۟ فَتَحَسَّسُوا۟ مِن يُوسُفَ وَأَخِيهِ وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ ۖ إِنَّهُۥ لَا يَا۟يْـَٔسُ مِن رَّوْحِ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْكَـٰفِرُونَ","en":"O my sons, go and find out about Joseph and his brother and despair not of relief from Allāh. Indeed, no one despairs of relief from Allāh except the disbelieving people.\"","ur":"بیٹا (یوں کرو کہ ایک دفعہ پھر) جاؤ اور یوسف اور اس کے بھائی کو تلاش کرو اور خدا کی رحمت سے ناامید نہ ہو۔ کہ خدا کی رحمت سے بےایمان لوگ ناامید ہوا کرتے ہیں","hi":"ऐ मेरे बेटो! जाओ और यूसुफ़ तथा उसके भाई का पता लगाओ। और अल्लाह की दया से निराश न हो। वास्तव में, अल्लाह की दया से वही निराश होते हैं, जो काफ़िर हैं।"},{"a":88,"ar":"فَلَمَّا دَخَلُوا۟ عَلَيْهِ قَالُوا۟ يَـٰٓأَيُّهَا ٱلْعَزِيزُ مَسَّنَا وَأَهْلَنَا ٱلضُّرُّ وَجِئْنَا بِبِضَـٰعَةٍ مُّزْجَىٰةٍ فَأَوْفِ لَنَا ٱلْكَيْلَ وَتَصَدَّقْ عَلَيْنَآ ۖ إِنَّ ٱللَّهَ يَجْزِى ٱلْمُتَصَدِّقِينَ","en":"So when they entered upon him [i.e., Joseph], they said, \"O ʿAzeez, adversity has touched us and our family, and we have come with goods poor in quality, but give us full measure and be charitable to us. Indeed, Allāh rewards the charitable.\"","ur":"جب وہ یوسف کے پاس گئے تو کہنے لگے کہ عزیز ہمیں اور ہمارے اہل وعیال کو بڑی تکلیف ہو رہی ہے اور ہم تھوڑا سا سرمایہ لائے ہیں آپ ہمیں (اس کے عوض) پورا غلّہ دے دیجیئے اور خیرات کیجیئے۔ کہ خدا خیرات کرنے والوں کو ثواب دیتا ہے","hi":"फिर जब (यूसुफ़ के भाई) उनके पास (मिस्र) गए, तो कहा : ऐ अज़ीज़! हमपर और हमारे घर वालों पर विपत्ति (अकाल) आ पड़ी है और हम थोड़ा-सा धन (मूल्य) लाए हैं। लेकिन हमें पूरी-पूरी माप प्रदान करें और हमें दान (भी) दें। निःसंदेह अल्लाह दान करने वालों को बदला देता है।"},{"a":89,"ar":"قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذْ أَنتُمْ جَـٰهِلُونَ","en":"He said, \"Do you know what you did with Joseph and his brother when you were ignorant?\"","ur":"(یوسف نے) کہا تمہیں معلوم ہے جب تم نادانی میں پھنسے ہوئے تھے تو تم نے یوسف اور اس کے بھائی کے ساتھ کیا کیا تھا","hi":"यूसुफ़ ने कहा : क्या तुम्हें ज्ञात है कि तुमने यूसुफ़ तथा उसके भाई के साथ क्या कुछ किया, जब तुम नासमझ थे?"},{"a":90,"ar":"قَالُوٓا۟ أَءِنَّكَ لَأَنتَ يُوسُفُ ۖ قَالَ أَنَا۠ يُوسُفُ وَهَـٰذَآ أَخِى ۖ قَدْ مَنَّ ٱللَّهُ عَلَيْنَآ ۖ إِنَّهُۥ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ","en":"They said, \"Are you indeed Joseph?\" He said, \"I am Joseph, and this is my brother. Allāh has certainly favored us. Indeed, he who fears Allāh and is patient, then indeed, Allāh does not allow to be lost the reward of those who do good.\"","ur":"وہ بولے کیا تم ہی یوسف ہو؟ انہوں نے کہا ہاں میں ہی یوسف ہوں۔ اور (بنیامین کی طرف اشارہ کرکے کہنے لگے) یہ میرا بھائی ہے خدا نے ہم پر بڑا احسان کیا ہے۔ جو شخص خدا سے ڈرتا اور صبر کرتا ہے تو خدا نیکوکاروں کا اجر ضائع نہیں کرتا","hi":"उन्होंने कहा : क्या निश्चय वास्तव में आप ही यूसुफ़ हैं? यूसुफ़ ने कहा : मैं यूसुफ़ हूँ और यह मेरा भाई है। निश्चय अल्लाह ने हमपर उपकार किया है। निःसंदेह जो (अल्लाह से) डरता है तथा धैर्य रखता है, तो अल्लाह सदाचारियों का प्रतिफल नष्ट नहीं करता।"},{"a":91,"ar":"قَالُوا۟ تَٱللَّهِ لَقَدْ ءَاثَرَكَ ٱللَّهُ عَلَيْنَا وَإِن كُنَّا لَخَـٰطِـِٔينَ","en":"They said, \"By Allāh, certainly has Allāh preferred you over us, and indeed, we have been sinners.\"","ur":"وہ بولے خدا کی قسم خدا نے تم کو ہم پر فضیلت بخشی ہے اور بےشک ہم خطاکار تھے","hi":"उन्होंने कहा : अल्लाह की क़सम! निश्चय अल्लाह ने आपको हमपर श्रेष्ठता प्रदान की है। निःसंदेह हम वास्तव में दोषी थे।"},{"a":92,"ar":"قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ ۖ يَغْفِرُ ٱللَّهُ لَكُمْ ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ","en":"He said, \"No blame will there be upon you today. May Allāh forgive you; and He is the most merciful of the merciful.","ur":"(یوسف نے) کہا کہ آج کے دن سے تم پر کچھ عتاب (وملامت) نہیں ہے۔ خدا تم کو معاف کرے۔ اور وہ بہت رحم کرنے والا ہے","hi":"यूसुफ़ ने कहा : आज तुम्हारी कोई भर्त्सना नहीं की जाएगी। अल्लाह तुम्हें क्षमा करे। वह दया करने वालों में सबसे अधिक दया करने वाला है।"},{"a":93,"ar":"ٱذْهَبُوا۟ بِقَمِيصِى هَـٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِى يَأْتِ بَصِيرًا وَأْتُونِى بِأَهْلِكُمْ أَجْمَعِينَ","en":"Take this, my shirt, and cast it over the face of my father; he will become seeing. And bring me your family, all together.\"","ur":"یہ میرا کرتہ لے جاؤ اور اسے والد صاحب کے منہ پر ڈال دو۔ وہ بینا ہو جائیں گے۔ اور اپنے تمام اہل وعیال کو میرے پاس لے آؤ","hi":"मेरा यह कुर्ता ले जाओ और उसे मेरे पिता के चेहरे पर डाल दो, वह देखने लगेंगे। और अपने सभी घर वालों को मेरे पास ले आओ।"},{"a":94,"ar":"وَلَمَّا فَصَلَتِ ٱلْعِيرُ قَالَ أَبُوهُمْ إِنِّى لَأَجِدُ رِيحَ يُوسُفَ ۖ لَوْلَآ أَن تُفَنِّدُونِ","en":"And when the caravan departed [from Egypt], their father said, \"Indeed, I find the smell of Joseph [and would say that he was alive] if you did not think me weakened in mind.\"","ur":"اور جب قافلہ (مصر سے) روانہ ہوا تو ان کے والد کہنے لگے کہ اگر مجھ کو یہ نہ کہو کہ (بوڑھا) بہک گیا ہے تو مجھے تو یوسف کی بو آ رہی ہے","hi":"और जब क़ाफ़िला चल पड़ा, तो उनके पिता ने कहा : निःसंदेह मुझे यूसुफ़ की सुगंध आ रही है, यदि तुम मुझे बहका हुआ न समझो।"},{"a":95,"ar":"قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِى ضَلَـٰلِكَ ٱلْقَدِيمِ","en":"They said, \"By Allāh, indeed you are in your [same] old error.\"","ur":"وہ بولے کہ والله آپ اسی قدیم غلطی میں (مبتلا) ہیں","hi":"उन लोगों ने कहा : अल्लाह की क़सम! निश्चय आप अपनी पुरानी भ्रांति ही में पड़े हुए हैं।"},{"a":96,"ar":"فَلَمَّآ أَن جَآءَ ٱلْبَشِيرُ أَلْقَىٰهُ عَلَىٰ وَجْهِهِۦ فَٱرْتَدَّ بَصِيرًا ۖ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ","en":"And when the bearer of good tidings arrived, he cast it over his face, and he returned [once again] seeing. He said, \"Did I not tell you that I know from Allāh that which you do not know?\"","ur":"جب خوشخبری دینے والا آ پہنچا تو کرتہ یعقوب کے منہ پر ڈال دیا اور وہ بینا ہو گئے (اور بیٹوں سے) کہنے لگے کیا میں نے تم سے نہیں کہا تھا کہ میں خدا کی طرف سے وہ باتیں جانتا ہوں جو تم نہیں جانتے","hi":"फिर जैसे ही शुभ सूचना देने वाला आया, उसने वह (कुर्ता) उनके मुख पर डाल दिया तो वह फिर से देखने लगे। कहने लगे : क्या मैंने तुमसे कहा नहीं था कि निःसंदेह मैं अल्लाह की ओर से जो जानता हूँ, तुम नहीं जानते?"},{"a":97,"ar":"قَالُوا۟ يَـٰٓأَبَانَا ٱسْتَغْفِرْ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَـٰطِـِٔينَ","en":"They said, \"O our father, ask for us forgiveness of our sins; indeed, we have been sinners.\"","ur":"بیٹوں نے کہا کہ ابا ہمارے لیے ہمارے گناہ کی مغفرت مانگیئے۔ بےشک ہم خطاکار تھے","hi":"उन्होंने कहा : ऐ हमारे पिता! हमारे लिए हमारे पापों की क्षमा के लिए प्रार्थना करें। निश्चय हम ही दोषी थे।"},{"a":98,"ar":"قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّىٓ ۖ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ","en":"He said, \"I will ask forgiveness for you from my Lord. Indeed, it is He who is the Forgiving, the Merciful.\"","ur":"انہوں نے کہا کہ میں اپنے پروردگار سے تمہارے لیے بخشش مانگوں گا۔ بےشک وہ بخشنے والا مہربان ہے","hi":"उस (याक़ूब) ने कहा : मैं तुम्हारे लिए अपने पालनहार से क्षमा की प्रार्थना करूँगा। निःसंदेह वही अत्यंत क्षमा करने वाला, असीम दयावान् है।"},{"a":99,"ar":"فَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَبَوَيْهِ وَقَالَ ٱدْخُلُوا۟ مِصْرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ","en":"And when they entered upon Joseph, he took his parents to himself [i.e., embraced them] and said, \"Enter Egypt, Allāh willing, safe [and secure].\"","ur":"جب یہ (سب لوگ) یوسف کے پاس پہنچے تو یوسف نے اپنے والدین کو اپنے پاس بٹھایا اور کہا مصر میں داخل ہو جائیے خدا نے چاہا تو جمع خاطر سے رہیئے گا","hi":"फिर जब वे यूसुफ़ के पास पहुँचे, तो उन्होंने अपने माता-पिता को अपने पास जगह दी और कहा : सुरक्षित वि निश्चिंत मिस्र में प्रवेश करो, यदि अल्लाह ने चाहा।"},{"a":100,"ar":"وَرَفَعَ أَبَوَيْهِ عَلَى ٱلْعَرْشِ وَخَرُّوا۟ لَهُۥ سُجَّدًا ۖ وَقَالَ يَـٰٓأَبَتِ هَـٰذَا تَأْوِيلُ رُءْيَـٰىَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّى حَقًّا ۖ وَقَدْ أَحْسَنَ بِىٓ إِذْ أَخْرَجَنِى مِنَ ٱلسِّجْنِ وَجَآءَ بِكُم مِّنَ ٱلْبَدْوِ مِنۢ بَعْدِ أَن نَّزَغَ ٱلشَّيْطَـٰنُ بَيْنِى وَبَيْنَ إِخْوَتِىٓ ۚ إِنَّ رَبِّى لَطِيفٌ لِّمَا يَشَآءُ ۚ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ","en":"And he raised his parents upon the throne, and they bowed to him in prostration. And he said, \"O my father, this is the explanation of my vision of before. My Lord has made it reality. And He was certainly good to me when He took me out of prison and brought you [here] from bedouin life after Satan had induced [estrangement] between me and my brothers. Indeed, my Lord is Subtle in what He wills. Indeed, it is He who is the Knowing, the Wise.","ur":"اور اپنے والدین کو تخت پر بٹھایا اور سب یوسفؑ کے آگے سجدہ میں گر پڑے اور (اس وقت) یوسف نے کہا ابا جان یہ میرے اس خواب کی تعبیر ہے جو میں نے پہلے (بچپن میں) دیکھا تھا۔ میرے پروردگار نے اسے سچ کر دکھایا اور اس نے مجھ پر (بہت سے) احسان کئے ہیں کہ مجھ کو جیل خانے سے نکالا۔ اور اس کے بعد کہ شیطان نے مجھ میں اور میرے بھائیوں میں فساد ڈال دیا تھا۔ آپ کو گاؤں سے یہاں لایا۔ بےشک میرا پروردگار جو چاہتا ہے تدبیر سے کرتا ہے۔ وہ دانا (اور) حکمت والا ہے","hi":"तथा उसने अपने माता-पिता को सिंहासन पर ऊँचा बिठाया और सब उन (यूसुफ़) के आगे सजदे में गिर गए और यूसुफ़ ने कहा : ऐ मेरे पिता! यह मेरे पहले के स्वप्न का अर्थ है। निःसंदेह मेरे पालनहार ने उसे सच कर दिया। तथा निःसंदेह उसने मुझपर उपकार किया, जब मुझे कारावास से निकाला और आप लोगों को गाँव से ले आया, इसके पश्चात् कि शैतान ने मेरे तथा मेरे भाइयों के बीच झगड़ा डाल दिया। निःसंदेह मेरा पालनहार जो चाहे, उसका सूक्ष्म उपाय करने वाला है। निश्चय वही सब कुछ जानने वाला, पूर्ण हिकमत वाला है।"},{"a":101,"ar":"۞ رَبِّ قَدْ ءَاتَيْتَنِى مِنَ ٱلْمُلْكِ وَعَلَّمْتَنِى مِن تَأْوِيلِ ٱلْأَحَادِيثِ ۚ فَاطِرَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ أَنتَ وَلِىِّۦ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۖ تَوَفَّنِى مُسْلِمًا وَأَلْحِقْنِى بِٱلصَّـٰلِحِينَ","en":"My Lord, You have given me [something] of sovereignty and taught me of the interpretation of dreams. Creator of the heavens and earth, You are my protector in this world and the Hereafter. Cause me to die a Muslim and join me with the righteous.\"","ur":"(جب یہ سب باتیں ہولیں تو یوسف نے خدا سے دعا کی کہ) اے میرے پروردگار تو نے مجھ کو حکومت سے بہرہ دیا اور خوابوں کی تعبیر کا علم بخشا۔ اے آسمانوں اور زمین کے پیدا کرنے والے تو ہی دنیا اور آخرت میں میرا کارساز ہے۔ تو مجھے (دنیا سے) اپنی اطاعت (کی حالت) میں اٹھائیو اور (آخرت میں) اپنے نیک بندوں میں داخل کیجیو","hi":"ऐ मेरे पालनहार! तूने मुझे राज्य में से हिस्सा प्रदान किया तथा बातों के अर्थ (असल तथ्य) में से कुछ सिखाया। ऐ आकाशों तथा धरती के पैदा करने वाले! दुनिया तथा आख़िरत में तू ही मेरा संरक्षक है। मुझे मुसलमान होने की अवस्था में मृत्यु दे और मुझे सदाचारियों से मिला दे।"},{"a":102,"ar":"ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ ۖ وَمَا كُنتَ لَدَيْهِمْ إِذْ أَجْمَعُوٓا۟ أَمْرَهُمْ وَهُمْ يَمْكُرُونَ","en":"That is from the news of the unseen which We reveal, [O Muḥammad], to you. And you were not with them when they put together their plan while they conspired.","ur":"(اے پیغمبر) یہ اخبار غیب میں سے ہیں جو ہم تمہاری طرف بھیجتے ہیں اور جب برادران یوسف نے اپنی بات پر اتفاق کیا تھا اور وہ فریب کر رہے تھے تو تم ان کے پاس تو نہ تھے","hi":"(ऐ नबी!) ये ग़ैब (परोक्ष) के कुछ समाचार हैं, जो हम आपकी ओर वह़्य करते हैं। और आप उन (भाइयों) के पास नहीं थे, जब उन्होंने अपने काम का दृढ़ निश्चय किया और वे गुप्त उपाय कर रहे थे।"},{"a":103,"ar":"وَمَآ أَكْثَرُ ٱلنَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ","en":"And most of the people, although you strive [for it], are not believers.","ur":"اور بہت سے آدمی گو تم (کتنی ہی) خواہش کرو ایمان لانے والے نہیں ہیں","hi":"और अधिकांश लोग, अगरचे आप उत्सुक हों, हरगिज़ ईमान लाने वाले नहीं हैं।"},{"a":104,"ar":"وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنْ أَجْرٍ ۚ إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَـٰلَمِينَ","en":"And you do not ask of them for it any payment. It is not except a reminder to the worlds.","ur":"اور تم ان سے اس (خیر خواہی) کا کچھ صلا بھی تو نہیں مانگتے۔ یہ قرآن اور کچھ نہیں تمام عالم کے لیے نصیحت ہے","hi":"हालाँकि आप उनसे इस (धर्म प्रचार) पर कोई पारिश्रमिक नहीं माँगते। यह (क़ुरआन) तो संसार वालों के लिए मात्र एक उपदेश है।"},{"a":105,"ar":"وَكَأَيِّن مِّنْ ءَايَةٍ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ","en":"And how many a sign within the heavens and earth do they pass over while they, therefrom, are turning away.","ur":"اور آسمان و زمین میں بہت سی نشانیاں ہیں جن پر یہ گزرتے ہیں اور ان سے اعراض کرتے ہیں","hi":"तथा आकाशों और धरती में कितनी ही निशानियाँ हैं, जिनपर से वे गुज़रते हैं और वे उनपर ध्यान नहीं देते।"},{"a":106,"ar":"وَمَا يُؤْمِنُ أَكْثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشْرِكُونَ","en":"And most of them believe not in Allāh except while they associate others with Him.","ur":"اور یہ اکثر خدا پر ایمان نہیں رکھتے۔ مگر (اس کے ساتھ) شرک کرتے ہیں","hi":"और उनमें से अधिकांश अल्लाह पर ईमान नहीं रखते, परंतु इस हाल में कि वे साझी ठहराने वाले होते हैं।"},{"a":107,"ar":"أَفَأَمِنُوٓا۟ أَن تَأْتِيَهُمْ غَـٰشِيَةٌ مِّنْ عَذَابِ ٱللَّهِ أَوْ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ","en":"Then do they feel secure that there will not come to them an overwhelming [aspect] of the punishment of Allāh or that the Hour will not come upon them suddenly while they do not perceive?","ur":"کیا یہ اس (بات) سے بےخوف ہیں کہ ان پر خدا کا عذاب نازل ہو کر ان کو ڈھانپ لے یا ان پر ناگہاں قیامت آجائے اور انہیں خبر بھی نہ ہو","hi":"तो क्या वे निर्भय हो गए हैं कि उनपर अल्लाह की यातना में से कोई ढांक लेने वाली विपत्ति आ पड़े, या उनपर अचानक क़ियामत आ जाए और वे सोचते भी न हों?"},{"a":108,"ar":"قُلْ هَـٰذِهِۦ سَبِيلِىٓ أَدْعُوٓا۟ إِلَى ٱللَّهِ ۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِى ۖ وَسُبْحَـٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ","en":"Say, \"This is my way; I invite to Allāh with insight, I and those who follow me. And exalted is Allāh; and I am not of those who associate others with Him.\"","ur":"کہہ دو میرا رستہ تو یہ ہے میں خدا کی طرف بلاتا ہوں (از روئے یقین وبرہان) سمجھ بوجھ کر میں بھی (لوگوں کو خدا کی طرف بلاتا ہوں) اور میرے پیرو بھی۔ اور خدا پاک ہے۔ اور میں شرک کرنے والوں میں سے نہیں ہوں","hi":"(ऐ नबी!) आप कह दें : यही मेरा रास्ता है। मैं और मेरा अनुसरण करने वाले पूर्ण अंतर्दृष्टि तथा स्पष्ट प्रमाण के साथ अल्लाह की ओर बुलाते हैं। तथा अल्लाह पवित्र है और मैं मुश्रिकों (बहुदेववादियों) में से नहीं हूँ।"},{"a":109,"ar":"وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِم مِّنْ أَهْلِ ٱلْقُرَىٰٓ ۗ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۗ وَلَدَارُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ٱتَّقَوْا۟ ۗ أَفَلَا تَعْقِلُونَ","en":"And We sent not before you [as messengers] except men to whom We revealed from among the people of cities. So have they not traveled through the earth and observed how was the end of those before them? And the home of the Hereafter is best for those who fear Allāh; then will you not reason?","ur":"اور ہم نے تم سے پہلے بستیوں کے رہنے والوں میں سے مرد ہی بھیجے تھے جن کی طرف ہم وحی بھیجتے تھے۔ کیا ان لوگوں نے ملک میں سیر (وسیاحت) نہیں کی کہ دیکھ لیتے کہ جو لوگ ان سے پہلے تھے ان کا انجام کیا ہوا۔ اور متّقیوں کے لیے آخرت کا گھر بہت اچھا ہے۔ کیا تم سمجھتے نہیں؟","hi":"और हमने आपसे पहले बस्तियों के रहने वालों में से केवल पुरुषों को नबी बनाकर भेजे, जिनकी ओर हम वह़्य किया करते थे। तो क्या ये धरती में चले-फिरे नहीं, कि देखते उनका परिणाम कैसा हुआ, जो इनसे पहले थे? और निश्चय आख़िरत (परलोक) का घर उनके लिए उत्तम है, जो अल्लाह से डरते रहे। तो क्या तुम समझते नहीं?"},{"a":110,"ar":"حَتَّىٰٓ إِذَا ٱسْتَيْـَٔسَ ٱلرُّسُلُ وَظَنُّوٓا۟ أَنَّهُمْ قَدْ كُذِبُوا۟ جَآءَهُمْ نَصْرُنَا فَنُجِّىَ مَن نَّشَآءُ ۖ وَلَا يُرَدُّ بَأْسُنَا عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ","en":"[They continued] until, when the messengers despaired and were certain that they had been denied, there came to them Our victory, and whoever We willed was saved. And Our punishment cannot be repelled from the people who are criminals.","ur":"یہاں تک کہ جب پیغمبر ناامید ہوگئے اور انہوں نے خیال کیا کہ اپنی نصرت کے بارے میں جو بات انہوں نے کہی تھی (اس میں) وہ سچے نہ نکلے تو ان کے پاس ہماری مدد آ پہنچی۔ پھر جسے ہم نے چاہا بچا دیا۔ اور ہمارا عذاب (اتر کر) گنہگار لوگوں سے پھرا نہیں کرتا","hi":"यहाँ तक कि जब रसूल बिलकुल निराश हो गए और लोगों को विश्वास हो गया कि निश्चय उनसे झूठ बोला गया था, तो उनके पास हमारी सहायता आ गई। फिर हम जिसे चाहते थे, उसे बचा लिया गया। और हमारी यातना अपराधियों से हटाई नहीं जाती।"},{"a":111,"ar":"لَقَدْ كَانَ فِى قَصَصِهِمْ عِبْرَةٌ لِّأُو۟لِى ٱلْأَلْبَـٰبِ ۗ مَا كَانَ حَدِيثًا يُفْتَرَىٰ وَلَـٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ","en":"There was certainly in their stories a lesson for those of understanding. Never was it [i.e., the Qur’ān] a narration invented, but a confirmation of what was before it and a detailed explanation of all things and guidance and mercy for a people who believe.","ur":"ان کے قصے میں عقلمندوں کے لیے عبرت ہے۔ یہ (قرآن) ایسی بات نہیں ہے جو (اپنے دل سے) بنائی گئی ہو بلکہ جو (کتابیں) اس سے پہلے نازل ہوئی ہیں ان کی تصدیق (کرنے والا) ہے اور مومنوں کے لیے ہدایت اور رحمت ہے","hi":"निःसंदेह उनकी कहानियों में, बुद्धिमानों के लिए बड़ी शिक्षा है। यह (क़ुरआन) हरगिज़ ऐसी बात नहीं, जो गढ़ ली जाए। लेकिन इससे पहले की पुस्तकों की पुष्टि करने वाला और प्रत्येक वस्तु का विवरण (ब्योरा) है, तथा उन लोगों के लिए, जो ईमान (विश्वास) रखते हैं, मार्गदर्शन और दया है।"}],"tlx":{"hi":"यूसुफ़","ur":"یوسف"}};
